screenPanels.initJs:
function(container, apiUrl, tables) {
  // テーブルインデックス: 重複受注検出結果テーブルを想定
  const tableIndex = 0;
  const tbody = container.querySelector("#duplicate-tbody");
  const comparePanel = container.querySelector("#compare-panel");
  const comparePairInfo = container.querySelector("#compare-pair-info");
  const compareRule = container.querySelector("#compare-rule");
  const compareConfidence = container.querySelector("#compare-confidence");
  const compareReason = container.querySelector("#compare-reason");
  const actionPolicy = container.querySelector("#action-policy");
  const confirmUser = container.querySelector("#confirm-user");
  const compareNotes = container.querySelector("#compare-notes");

  let allRows = [];
  let selectedPair = null;

  // 1. テーブル再描画関数
  function renderRows(rows) {
    allRows = rows;
    tbody.innerHTML = rows.map(r => {
      const scoreClass = r.マッチング信頼度 >= 90 ? 'high' : r.マッチング信頼度 >= 70 ? 'medium' : 'low';
      const scoreColor = r.マッチング信頼度 >= 90 ? '#4ade80' : r.マッチング信頼度 >= 70 ? '#fbbf24' : '#ef4444';
      return `
        <tr data-id="${r.id}" style="border-bottom: 1px solid var(--border); cursor: pointer;" class="duplicate-row">
          <td style="padding: 8px; color: var(--text);">${r.主受注ID || '—'}</td>
          <td style="padding: 8px; color: var(--text);">${r.顧客名 || '—'}</td>
          <td style="padding: 8px; color: var(--text); font-size: 11px;">${r.受注日時 ? new Date(r.受注日時).toLocaleString('ja-JP') : '—'}</td>
          <td style="padding: 8px; color: var(--text);">${r.チャネル || '—'}</td>
          <td style="padding: 8px; color: var(--text); text-align: right;">¥${(r.金額 || 0).toLocaleString()}</td>
          <td style="padding: 8px; text-align: center;">
            <span style="background: ${scoreColor}; color: #fff; padding: 2px 6px; border-radius: 3px; font-size: 11px; font-weight: 600;">
              ${r.マッチング信頼度 || 0}%
            </span>
          </td>
          <td style="padding: 8px; text-align: center;">
            <span style="background: ${r.検出ステータス === '確認済み' ? 'rgba(74,222,128,0.2)' : r.検出ステータス === '統合済み' ? 'rgba(96,165,250,0.2)' : 'rgba(248,113,113,0.2)'}; color: var(--text); padding: 2px 6px; border-radius: 3px; font-size: 11px;">
              ${r.検出ステータス || '未確認'}
            </span>
          </td>
          <td style="padding: 8px; text-align: center;">
            <button class="action-btn secondary compare-btn" data-id="${r.id}" style="padding: 4px 8px; font-size: 11px;">比較</button>
          </td>
        </tr>
      `;
    }).join("");

    if (rows.length === 0) {
      tbody.innerHTML = `<tr style="background: var(--bg-main); color: var(--text-muted);"><td colspan="8" style="padding: 16px; text-align: center;">重複受注が見つかりません</td></tr>`;
    }
  }

  // 2. 初期データ描画
  renderRows(tables[tableIndex]?.records || []);

  // 3. 検索ボタン
  container.querySelector("#btn-search").addEventListener("click", async () => {
    const keyword = container.querySelector("#search-keyword").value.toLowerCase();
    const scoreRange = container.querySelector("#filter-score-range").value;
    const status = container.querySelector("#filter-status").value;

    const rows = await window.aivicApi.list(tableIndex) || allRows;
    const filtered = rows.filter(r => {
      const matchKeyword = !keyword || 
        (r.主受注ID || '').toLowerCase().includes(keyword) ||
        (r.副受注ID || '').toLowerCase().includes(keyword) ||
        (r.顧客名 || '').toLowerCase().includes(keyword);

      const matchScore = !scoreRange || (() => {
        const [min, max] = scoreRange.split('-').map(Number);
        return r.マッチング信頼度 >= min && r.マッチング信頼度 <= max;
      })();

      const matchStatus = !status || r.検出ステータス === status;

      return matchKeyword && matchScore && matchStatus;
    });

    renderRows(filtered);
  });

  // 4. 比較ボタンのイベントデリゲーション
  container.addEventListener("click", e => {
    const compareBtn = e.target.closest(".compare-btn");
    if (compareBtn) {
      const rowId = compareBtn.dataset.id;
      const row = allRows.find(r => r.id === rowId);
      if (row) {
        selectedPair = row;
        displayComparison(row);
      }
    }
  });

  // 5. 比較パネル表示関数
  function displayComparison(pair) {
    comparePairInfo.textContent = `主受注: ${pair.主受注ID} ↔ 副受注: ${pair.副受注ID}`;
    compareRule.textContent = pair.検出ルールID || '—';
    compareConfidence.textContent = `${pair.マッチング信頼度 || 0}%`;
    compareReason.textContent = pair.マッチング理由 || '—';
    actionPolicy.value = pair.対応方針 || '';
    confirmUser.value = pair.確認者名 || '';
    compareNotes.value = pair.備考 || '';

    // 比較パネルの詳細表示（簡略版）
    comparePanel.innerHTML = `
      <div style="background: var(--bg-main); border: 1px solid var(--border); border-radius: 4px; padding: 12px;">
        <div style="font-size: 11px; color: var(--text-muted); margin-bottom: 8px; font-weight: 600;">主受注データ</div>
        <div style="font-size: 12px; color: var(--text); line-height: 1.6;">
          <div><strong>受注ID:</strong> ${pair.主受注ID || '—'}</div>
          <div><strong>顧客名:</strong> ${pair.顧客名 || '—'}</div>
          <div><strong>受注日時:</strong> ${pair.受注日時 ? new Date(pair.受注日時).toLocaleString('ja-JP') : '—'}</div>
          <div><strong>チャネル:</strong> ${pair.チャネル || '—'}</div>
          <div><strong>金額:</strong> ¥${(pair.金額 || 0).toLocaleString()}</div>
        </div>
      </div>
      <div style="background: var(--bg-main); border: 1px solid var(--border); border-radius: 4px; padding: 12px;">
        <div style="font-size: 11px; color: var(--text-muted); margin-bottom: 8px; font-weight: 600;">副受注データ</div>
        <div style="font-size: 12px; color: var(--text); line-height: 1.6;">
          <div><strong>受注ID:</strong> ${pair.副受注ID || '—'}</div>
          <div><strong>顧客名:</strong> ${pair.顧客名 || '—'}</div>
          <div><strong>受注日時:</strong> ${pair.受注日時 ? new Date(pair.受注日時).toLocaleString('ja-JP') : '—'}</div>
          <div><strong>チャネル:</strong> ${pair.チャネル || '—'}</div>
          <div><strong>金額:</strong> ¥${(pair.金額 || 0).toLocaleString()}</div>
        </div>
      </div>
    `;
  }

  // 6. 判定保存ボタン
  container.querySelector("#btn-save-compare").addEventListener("click", async () => {
    if (!selectedPair) {
      alert("比較対象を選択してください");
      return;
    }
    if (!actionPolicy.value) {
      alert("対応方針を選択してください");
      return;
    }

    const updateData = {
      対応方針: actionPolicy.value,
      確認者名: confirmUser.value,
      備考: compareNotes.value,
      検出ステータス: '確認済み',
      確認日時: new Date().toISOString()
    };

    const result = await window.aivicApi.update(tableIndex, selectedPair.id, updateData);
    if (result) {
      alert("判定を保存しました");
      const rows = await window.aivicApi.list(tableIndex) || allRows;
      renderRows(rows);
      selectedPair = null;
      comparePairInfo.textContent = "ペアを選択してください";
      comparePanel.innerHTML = `
        <div style="background: var(--bg-main); border: 1px dashed var(--border); border-radius: 4px; padding: 12px; display: flex; align-items: center; justify-content: center; color: var(--text-muted); font-size: 12px;">主受注データ</div>
        <div style="background: var(--bg-main); border: 1px dashed var(--border); border-radius: 4px; padding: 12px; display: flex; align-items: center; justify-content: center; color: var(--text-muted); font-size: 12px;">副受注データ</div>
      `;
    }
  });

  // 7. キャンセルボタン
  container.querySelector("#btn-cancel-compare").addEventListener("click", () => {
    selectedPair = null;
    comparePairInfo.textContent = "ペアを選択してください";
    comparePanel.innerHTML = `
      <div style="background: var(--bg-main); border: 1px dashed var(--border); border-radius: 4px; padding: 12px; display: flex; align-items: center; justify-content: center; color: var(--text-muted); font-size: 12px;">主受注データ</div>
      <div style="background: var(--bg-main); border: 1px dashed var(--border); border-radius: 4px; padding: 12px; display: flex; align-items: center; justify-content: center; color: var(--text-muted); font-size: 12px;">副受注データ</div>
    `;
    actionPolicy.value = '';
    confirmUser.value = '';
    compareNotes.value = '';
  });
}

function(container, apiUrl, tables) {
  // テーブルインデックスの特定
  const scoreTableIndex = tables.findIndex(t => t.tableName === "信頼度スコア") ?? 0;
  const ocrResultTableIndex = tables.findIndex(t => t.tableName === "AI_OCR読み込み結果") ?? 1;
  const correctionHistoryTableIndex = tables.findIndex(t => t.tableName === "受注データ修正履歴") ?? 2;
  const validationResultTableIndex = tables.findIndex(t => t.tableName === "受注データ検証結果") ?? 3;

  let currentOrderId = null;
  let currentScoreId = null;
  let allScores = [];
  let allOcrResults = [];
  let allCorrectionHistory = [];
  let allValidationResults = [];

  // 1. スコア一覧の再描画
  function renderScoreList(scores) {
    const listEl = container.querySelector("#score-list");
    listEl.innerHTML = scores.map(score => {
      const scoreValue = score.総合スコア || 0;
      const warningLevel = score.警告レベル || "低";
      const warningColor = warningLevel === "高" ? "#ff6a00" : warningLevel === "中" ? "#ffb800" : "#4a9eff";

      return `
        <div 
          class="score-item" 
          data-score-id="${score.信頼度スコアID}" 
          data-order-id="${score.受注データID}"
          style="
            padding: 8px;
            border-left: 3px solid ${warningColor};
            background: rgba(0,0,0,0.15);
            border-radius: 4px;
            cursor: pointer;
            transition: background 0.2s;
          "
          onmouseover="this.style.background='rgba(0,0,0,0.25)'"
          onmouseout="this.style.background='rgba(0,0,0,0.15)'"
        >
          <div style="font-size: 11px; font-weight: 600; color: var(--text); margin-bottom: 4px;">
            受注ID: ${score.受注データID?.substring(0, 8) || "N/A"}
          </div>
          <div style="display: flex; justify-content: space-between; align-items: center;">
            <div>
              <div style="font-size: 10px; color: var(--text-muted);">総合スコア</div>
              <div style="font-size: 14px; font-weight: 700; color: ${scoreValue >= 80 ? "#4a9eff" : scoreValue >= 60 ? "#ffb800" : "#ff6a00"};">
                ${scoreValue}
              </div>
            </div>
            <div style="text-align: right;">
              <div style="font-size: 10px; color: var(--text-muted);">警告</div>
              <div style="font-size: 11px; font-weight: 600; color: ${warningColor};">${warningLevel}</div>
            </div>
          </div>
          <div style="font-size: 9px; color: var(--text-muted); margin-top: 4px;">
            完全性: ${score.完全性スコア || 0} / 正確性: ${score.正確性スコア || 0} / 一貫性: ${score.一貫性スコア || 0}
          </div>
        </div>
      `;
    }).join("");

    // スコアアイテムのクリックイベント
    container.querySelectorAll(".score-item").forEach(item => {
      item.addEventListener("click", () => {
        currentOrderId = item.dataset.orderId;
        currentScoreId = item.dataset.scoreId;
        loadOrderDetails(currentOrderId, currentScoreId);
      });
    });
  }

  // 2. 受注詳細情報の読み込みと表示
  function loadOrderDetails(orderId, scoreId) {
    const score = allScores.find(s => s.信頼度スコアID === scoreId);
    const ocrResult = allOcrResults.find(o => o.order_id === orderId);
    const validationResults = allValidationResults.filter(v => v.受注データID === orderId);

    // 選択中の受注情報を表示
    const infoEl = container.querySelector("#selected-order-info");
    infoEl.innerHTML = `
      <div style="margin-bottom: 6px;">
        <span style="color: var(--text-muted);">受注ID:</span>
        <span style="color: var(--text); font-weight: 600;">${orderId?.substring(0, 12) || "N/A"}</span>
      </div>
      <div style="margin-bottom: 6px;">
        <span style="color: var(--text-muted);">総合スコア:</span>
        <span style="color: var(--text); font-weight: 600;">${score?.総合スコア || 0}</span>
      </div>
      <div style="margin-bottom: 6px;">
        <span style="color: var(--text-muted);">警告フラグ:</span>
        <span style="color: ${score?.警告フラグ ? "#ff6a00" : "#4a9eff"}; font-weight: 600;">
          ${score?.警告フラグ ? "⚠ あり" : "✓ なし"}
        </span>
      </div>
    `;

    // 修正対象項目テーブルの描画
    const tbody = container.querySelector("#correction-items-tbody");
    tbody.innerHTML = validationResults.map(vr => `
      <tr style="border-bottom: 1px solid rgba(255,255,255,0.08);">
        <td style="padding: 6px 4px; color: var(--text);">${vr.検証項目 || "N/A"}</td>
        <td style="text-align: center; padding: 6px 4px; color: var(--text);">
          <span style="
            display: inline-block;
            padding: 2px 6px;
            border-radius: 3px;
            background: ${vr.重要度 === "致命的" ? "rgba(255,106,0,0.2)" : vr.重要度 === "高" ? "rgba(255,184,0,0.2)" : "rgba(74,158,255,0.2)"};
            color: ${vr.重要度 === "致命的" ? "#ff6a00" : vr.重要度 === "高" ? "#ffb800" : "#4a9eff"};
            font-size: 10px;
            font-weight: 600;
          ">${vr.重要度 || "中"}</span>
        </td>
        <td style="text-align: center; padding: 6px 4px;">
          <button 
            class="edit-item-btn" 
            data-validation-id="${vr.検証結果ID}"
            data-field-name="${vr.検証項目}"
            data-before-value="${(vr.検証値 || "").replace(/"/g, "&quot;")}"
            style="
              padding: 3px 8px;
              font-size: 10px;
              background: var(--primary);
              color: #fff;
              border: none;
              border-radius: 3px;
              cursor: pointer;
            "
          >修正</button>
        </td>
      </tr>
    `).join("");

    // 修正ボタンのイベントリスナー
    container.querySelectorAll(".edit-item-btn").forEach(btn => {
      btn.addEventListener("click", () => {
        const fieldName = btn.dataset.fieldName;
        const beforeValue = btn.dataset.beforeValue;
        container.querySelector("#edit-field-name").value = fieldName;
        container.querySelector("#edit-before-value").value = beforeValue;
        container.querySelector("#edit-after-value").value = "";
        container.querySelector("#edit-reason").value = "";
        container.querySelector("#edit-comment").value = "";
      });
    });

    // 修正履歴の表示
    const historyTbody = container.querySelector("#correction-history-tbody");
    const orderHistory = allCorrectionHistory.filter(h => h.受注データID === orderId);
    historyTbody.innerHTML = orderHistory.slice(0, 5).map(h => `
      <tr style="border-bottom: 1px solid rgba(255,255,255,0.08);">
        <td style="padding: 4px 4px; color: var(--text); font-size: 10px;">${h.修正項目名 || "N/A"}</td>
        <td style="padding: 4px 4px; color: var(--text-muted); font-size: 10px;">${new Date(h.修正日時).toLocaleString("ja-JP") || "N/A"}</td>
        <td style="padding: 4px 4px; color: var(--text-muted); font-size: 10px;">${h.修正ユーザーID?.substring(0, 8) || "N/A"}</td>
      </tr>
    `).join("");
  }

  // 3. 検索・フィルタ処理
  container.querySelector("#btn-search").addEventListener("click", async () => {
    const orderId = container.querySelector("#search-order-id").value.trim();
    const minScore = parseInt(container.querySelector("#filter-score-min").value) || 0;
    const maxScore = parseInt(container.querySelector("#filter-score-max").value) || 100;
    const warningLevel = container.querySelector("#filter-warning-level").value;

    let filtered = allScores;

    if (orderId) {
      filtered = filtered.filter(s => s.受注データID?.includes(orderId));
    }

    filtered = filtered.filter(s => {
      const score = s.総合スコア || 0;
      if (score < minScore || score > maxScore) return false;
      if (warningLevel && s.警告レベル !== warningLevel) return false;
      return true;
    });

    renderScoreList(filtered);
  });

  // 4. 修正確定ボタン
  container.querySelector("#btn-save-correction").addEventListener("click", async () => {
    const fieldName = container.querySelector("#edit-field-name").value;
    const beforeValue = container.querySelector("#edit-before-value").value;
    const afterValue = container.querySelector("#edit-after-value").value;
    const reason = container.querySelector("#edit-reason").value;
    const comment = container.querySelector("#edit-comment").value;

    if (!fieldName || !afterValue || !reason) {
      alert("修正項目、修正後の値、修正理由は必須です");
      return;
    }

    const correctionData = {
      受注データID: currentOrderId,
      修正項目名: fieldName,
      修正前値: beforeValue,
      修正後値: afterValue,
      修正理由: reason,
      修正備考: comment,
      修正ユーザーID: "current-user-id",
      修正日時: new Date().toISOString()
    };

    const saved = await window.aivicApi.save(correctionHistoryTableIndex, correctionData);
    if (saved) {
      alert("修正を確定しました");
      container.querySelector("#edit-after-value").value = "";
      container.querySelector("#edit-reason").value = "";
      container.querySelector("#edit-comment").value = "";
      // 修正履歴を再読み込み
      const updated = await window.aivicApi.list(correctionHistoryTableIndex);
      if (updated) {
        allCorrectionHistory = updated;
        loadOrderDetails(currentOrderId, currentScoreId);
      }
    }
  });

  // 5. キャンセルボタン
  container.querySelector("#btn-cancel-correction").addEventListener("click", () => {
    container.querySelector("#edit-field-name").value = "";
    container.querySelector("#edit-before-value").value = "";
    container.querySelector("#edit-after-value").value = "";
    container.querySelector("#edit-reason").value = "";
    container.querySelector("#edit-comment").value = "";
  });

  // 6. 初期データ読み込み
  async function initializeData() {
    const scores = await window.aivicApi.list(scoreTableIndex);
    const ocrResults = await window.aivicApi.list(ocrResultTableIndex);
    const correctionHistory = await window.aivicApi.list(correctionHistoryTableIndex);
    const validationResults = await window.aivicApi.list(validationResultTableIndex);

    if (scores) allScores = scores;
    if (ocrResults) allOcrResults = ocrResults;
    if (correctionHistory) allCorrectionHistory = correctionHistory;
    if (validationResults) allValidationResults = validationResults;

    renderScoreList(allScores);
  }

  initializeData();
}

function(container, apiUrl, tables) {
  const tableIndex = 0; // 修正対象優先度リスト
  const pageSize = 20;
  let currentPage = 0;
  let allRows = [];
  let filteredRows = [];

  // ステータスの色付けヘルパー
  function getStatusColor(status) {
    switch(status) {
      case '未対応': return '#ff9800';
      case '対応中': return '#2196f3';
      case '完了': return '#4caf50';
      case '保留': return '#9c27b0';
      default: return 'var(--text)';
    }
  }

  function getPriorityBadge(level) {
    const colors = {
      '1': '#ff5252', // 最高
      '2': '#ff9800', // 高
      '3': '#ffc107', // 中
      '4': '#4caf50', // 低
      '5': '#90a4ae'  // 最低
    };
    const labels = {
      '1': '最高',
      '2': '高',
      '3': '中',
      '4': '低',
      '5': '最低'
    };
    return `<span style="display: inline-block; padding: 3px 8px; background: ${colors[level] || '#666'}; color: #fff; border-radius: 3px; font-weight: 600; font-size: 11px;">${labels[level] || level}</span>`;
  }

  // 1. 再描画関数
  function renderRows(rows) {
    const tbody = container.querySelector('#record-tbody');
    if (!rows || rows.length === 0) {
      tbody.innerHTML = '<tr style="background: var(--bg-main); border-bottom: 1px solid rgba(255,255,255,0.06);"><td colspan="9" style="padding: 24px 12px; text-align: center; color: var(--text-muted);">該当データなし</td></tr>';
      return;
    }

    const start = currentPage * pageSize;
    const end = start + pageSize;
    const pageRows = rows.slice(start, end);

    tbody.innerHTML = pageRows.map(r => {
      const priorityLevel = r.優先度レベル || r.priority_level || '3';
      const status = r.修正ステータス || r.status || '未対応';
      const errorType = r.エラー分類 || r.error_type || '不明';
      const confidence = r.信頼度スコア || r.confidence_score || 0;
      const detectedAt = r.検出日時 || r.detected_at || '-';
      const orderId = r.受注データID || r.order_id || '-';
      const channel = r.チャネル || r.channel || '-';
      const errorMsg = r.エラー内容 || r.error_message || '-';

      return `<tr data-id="${r.優先度リストID || r.id}" style="background: var(--bg-main); border-bottom: 1px solid rgba(255,255,255,0.06); hover: background: rgba(255,255,255,0.03);">
        <td style="padding: 8px 12px; color: var(--text);">${getPriorityBadge(priorityLevel)}</td>
        <td style="padding: 8px 12px; color: var(--text); font-family: monospace; font-size: 11px;">${orderId.substring(0, 12)}</td>
        <td style="padding: 8px 12px; color: var(--text);">${channel}</td>
        <td style="padding: 8px 12px; color: var(--text); max-width: 200px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;" title="${errorMsg}">${errorMsg}</td>
        <td style="padding: 8px 12px; text-align: center; color: var(--text);">
          <span style="display: inline-block; padding: 2px 6px; background: rgba(255,255,255,0.1); border-radius: 3px; font-weight: 600;">${confidence}%</span>
        </td>
        <td style="padding: 8px 12px; color: var(--text);">${errorType}</td>
        <td style="padding: 8px 12px; color: ${getStatusColor(status)}; font-weight: 600;">${status}</td>
        <td style="padding: 8px 12px; color: var(--text-muted); font-size: 11px;">${detectedAt}</td>
        <td style="padding: 8px 12px; text-align: center;">
          <button class="action-btn secondary edit-btn" data-id="${r.優先度リストID || r.id}" style="padding: 4px 8px; font-size: 11px;">詳細</button>
        </td>
      </tr>`;
    }).join('');

    // ページ情報更新
    const totalPages = Math.ceil(rows.length / pageSize);
    container.querySelector('[data-testid="page-info"]').textContent = `ページ ${currentPage + 1} / ${totalPages}`;
  }

  // 統計情報更新
  function updateStats(rows) {
    const total = rows.length;
    const pending = rows.filter(r => (r.修正ステータス || r.status) === '未対応').length;
    const inProgress = rows.filter(r => (r.修正ステータス || r.status) === '対応中').length;
    const completed = rows.filter(r => (r.修正ステータス || r.status) === '完了').length;

    container.querySelector('[data-testid="total-count"]').textContent = total;
    container.querySelector('[data-testid="pending-count"]').textContent = pending;
    container.querySelector('[data-testid="in-progress-count"]').textContent = inProgress;
    container.querySelector('[data-testid="completed-count"]').textContent = completed;
  }

  // 2. 初期データ読み込み
  async function loadInitialData() {
    const rows = await window.aivicApi.list(tableIndex);
    if (rows) {
      allRows = rows;
      filteredRows = rows;
      currentPage = 0;
      renderRows(filteredRows);
      updateStats(filteredRows);
      // ユーザー情報取得（簡易版）
      container.querySelector('[data-testid="current-user"]').textContent = 'システムユーザー';
    }
  }

  loadInitialData();

  // 3. 検索ボタン
  container.querySelector('#btn-search').addEventListener('click', () => {
    const priorityFilter = container.querySelector('[data-testid="priority-filter"]').value;
    const errorTypeFilter = container.querySelector('[data-testid="error-type-filter"]').value;
    const statusFilter = container.querySelector('[data-testid="status-filter"]').value;

    filteredRows = allRows.filter(r => {
      const priority = String(r.優先度レベル || r.priority_level || '3');
      const errorType = r.エラー分類 || r.error_type || '';
      const status = r.修正ステータス || r.status || '';

      const matchPriority = !priorityFilter || priority === priorityFilter;
      const matchErrorType = !errorTypeFilter || errorType.includes(errorTypeFilter);
      const matchStatus = !statusFilter || status === statusFilter;

      return matchPriority && matchErrorType && matchStatus;
    });

    currentPage = 0;
    renderRows(filteredRows);
    updateStats(filteredRows);
  });

  // 4. CSV出力ボタン
  container.querySelector('#btn-export').addEventListener('click', async () => {
    const rows = await window.aivicApi.list(tableIndex);
    if (!rows || rows.length === 0) {
      alert('エクスポートするデータがありません');
      return;
    }

    const headers = ['優先度', '受注ID', 'チャネル', 'エラー内容', '信頼度', '分類', '修正状態', '検出日時'];
    const csvContent = [
      '\uFEFF' + headers.join(','),
      ...rows.map(r => [
        r.優先度レベル || r.priority_level || '3',
        r.受注データID || r.order_id || '',
        r.チャネル || r.channel || '',
        `"${(r.エラー内容 || r.error_message || '').replace(/"/g, '""')}"`,
        r.信頼度スコア || r.confidence_score || 0,
        r.エラー分類 || r.error_type || '',
        r.修正ステータス || r.status || '',
        r.検出日時 || r.detected_at || ''
      ].join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `修正対象優先度リスト_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  });

  // 5. ページネーション
  container.querySelector('#btn-prev').addEventListener('click', () => {
    if (currentPage > 0) {
      currentPage--;
      renderRows(filteredRows);
    }
  });

  container.querySelector('#btn-next').addEventListener('click', () => {
    const totalPages = Math.ceil(filteredRows.length / pageSize);
    if (currentPage < totalPages - 1) {
      currentPage++;
      renderRows(filteredRows);
    }
  });

  // 6. 詳細ボタン（イベントデリゲーション）
  container.addEventListener('click', (e) => {
    const editBtn = e.target.closest('.edit-btn');
    if (editBtn) {
      const recordId = editBtn.dataset.id;
      const record = allRows.find(r => (r.優先度リストID || r.id) === recordId);
      if (record) {
        // 詳細確認・修正画面へ遷移
        window.showScreen('scr-1781413282852');
      }
    }
  });
}

function(container, apiUrl, tables) {
  // テーブルインデックス（受注データ検証結果テーブル）
  const tableIndex = 0;

  // 1. 再描画関数
  function renderRows(rows) {
    const tbody = container.querySelector("#validation-tbody");
    if (!rows || rows.length === 0) {
      tbody.innerHTML = '<tr style="background: rgba(0,0,0,0.05);"><td colspan="8" style="padding: 20px; text-align: center; color: var(--text-muted);">検証結果がありません</td></tr>';
      return;
    }

    tbody.innerHTML = rows.map(r => {
      const statusColor = r.検証ステータス === '合格' ? '#4CAF50' : 
                          r.検証ステータス === '警告' ? '#FF9800' : 
                          r.検証ステータス === '不合格' ? '#F44336' : '#2196F3';
      const priorityBg = r.修正優先度 === 1 ? 'rgba(244,67,54,0.2)' :
                         r.修正優先度 === 2 ? 'rgba(255,152,0,0.2)' :
                         r.修正優先度 === 3 ? 'rgba(255,193,7,0.2)' : 'rgba(76,175,80,0.2)';

      return `<tr data-id="${r.検証結果ID || ''}" style="border-bottom: 1px solid var(--border); hover:background: rgba(0,0,0,0.08);">
        <td style="padding: 8px; color: var(--text);">${r.受注データID ? r.受注データID.substring(0, 8) : '-'}</td>
        <td style="padding: 8px; color: var(--text);">${r.チャネル名 || '-'}</td>
        <td style="padding: 8px; text-align: center; color: var(--text);"><span style="background: ${statusColor}; color: #fff; padding: 2px 6px; border-radius: 3px; font-size: 11px;">${r.検証ステータス || '-'}</span></td>
        <td style="padding: 8px; text-align: center; color: var(--text);">${r.信頼度スコア || 0}%</td>
        <td style="padding: 8px; color: var(--text); max-width: 150px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;" title="${r.エラーメッセージ || ''}">${r.エラーコード || '-'}</td>
        <td style="padding: 8px; text-align: center;"><span style="background: ${priorityBg}; padding: 2px 6px; border-radius: 3px; font-size: 11px; color: var(--text);">P${r.修正優先度 || 5}</span></td>
        <td style="padding: 8px; text-align: center; color: var(--text);">${r.対応状況 || '未対応'}</td>
        <td style="padding: 8px; text-align: center;">
          <button class="action-btn secondary detail-btn" data-id="${r.検証結果ID || ''}" style="padding: 4px 8px; font-size: 11px;">詳細</button>
        </td>
      </tr>`;
    }).join("");
  }

  // 2. KPI 集計関数
  function updateKpis(rows) {
    const passed = rows.filter(r => r.検証ステータス === '合格').length;
    const warning = rows.filter(r => r.検証ステータス === '警告').length;
    const failed = rows.filter(r => r.検証ステータス === '不合格').length;
    const pending = rows.filter(r => r.検証ステータス === '保留').length;

    container.querySelector('[data-testid="kpi-passed"]').textContent = passed;
    container.querySelector('[data-testid="kpi-warning"]').textContent = warning;
    container.querySelector('[data-testid="kpi-failed"]').textContent = failed;
    container.querySelector('[data-testid="kpi-pending"]').textContent = pending;

    // エラー件数（重要度別）
    const critical = rows.filter(r => r.重要度 === '致命的').length;
    const high = rows.filter(r => r.重要度 === '高').length;
    const medium = rows.filter(r => r.重要度 === '中').length;
    const low = rows.filter(r => r.重要度 === '低').length;

    container.querySelector('[data-testid="error-critical"]').textContent = critical;
    container.querySelector('[data-testid="error-high"]').textContent = high;
    container.querySelector('[data-testid="error-medium"]').textContent = medium;
    container.querySelector('[data-testid="error-low"]').textContent = low;
  }

  // 3. 信頼度スコア分布グラフ
  function drawScoreDistribution(rows) {
    const canvas = container.querySelector('#score-distribution-chart');
    if (!canvas) return;
    const ctx = canvas.getContext('2d');

    // スコア範囲別の集計
    const ranges = [
      { label: '0-20', min: 0, max: 20, count: 0 },
      { label: '21-40', min: 21, max: 40, count: 0 },
      { label: '41-60', min: 41, max: 60, count: 0 },
      { label: '61-80', min: 61, max: 80, count: 0 },
      { label: '81-100', min: 81, max: 100, count: 0 }
    ];

    rows.forEach(r => {
      const score = r.信頼度スコア || 0;
      ranges.forEach(range => {
        if (score >= range.min && score <= range.max) range.count++;
      });
    });

    const maxCount = Math.max(...ranges.map(r => r.count), 1);
    const barWidth = canvas.width / ranges.length;
    const padding = 20;

    ctx.fillStyle = 'rgba(0,0,0,0)';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // グリッド線
    ctx.strokeStyle = 'rgba(255,255,255,0.1)';
    ctx.lineWidth = 1;
    for (let i = 0; i <= 5; i++) {
      const y = padding + (canvas.height - padding * 2) * (1 - i / 5);
      ctx.beginPath();
      ctx.moveTo(0, y);
      ctx.lineTo(canvas.width, y);
      ctx.stroke();
    }

    // バー描画
    ranges.forEach((range, idx) => {
      const barHeight = (canvas.height - padding * 2) * (range.count / maxCount);
      const x = idx * barWidth + barWidth * 0.1;
      const y = canvas.height - padding - barHeight;

      ctx.fillStyle = '#FFB74D';
      ctx.fillRect(x, y, barWidth * 0.8, barHeight);

      // ラベル
      ctx.fillStyle = '#d0e4ff';
      ctx.font = '11px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText(range.label, x + barWidth * 0.4, canvas.height - 5);
      ctx.fillText(range.count, x + barWidth * 0.4, y - 5);
    });
  }

  // 4. 初期データ読み込み
  async function loadData() {
    const rows = await window.aivicApi.list(tableIndex);
    if (rows) {
      renderRows(rows);
      updateKpis(rows);
      drawScoreDistribution(rows);
    }
  }

  // 5. 検索ボタン
  container.querySelector('[data-testid="search-button"]').addEventListener('click', async () => {
    const dateFrom = container.querySelector('[data-testid="validation-date-from"]').value;
    const dateTo = container.querySelector('[data-testid="validation-date-to"]').value;
    const channel = container.querySelector('[data-testid="channel-filter"]').value;

    const rows = await window.aivicApi.list(tableIndex);
    if (!rows) return;

    const filtered = rows.filter(r => {
      const validationDate = r.検証実行日時 ? r.検証実行日時.substring(0, 10) : '';
      const matchDate = (!dateFrom || validationDate >= dateFrom) && (!dateTo || validationDate <= dateTo);
      const matchChannel = !channel || r.チャネル名 === channel;
      return matchDate && matchChannel;
    });

    renderRows(filtered);
    updateKpis(filtered);
    drawScoreDistribution(filtered);
  });

  // 6. CSVエクスポート
  container.querySelector('[data-testid="export-button"]').addEventListener('click', async () => {
    const rows = await window.aivicApi.list(tableIndex);
    if (!rows || rows.length === 0) {
      alert('エクスポートするデータがありません');
      return;
    }

    const headers = ['受注ID', 'チャネル', '検証ステータス', '信頼度', 'エラーコード', '優先度', '対応状況'];
    const csvContent = [
      '\uFEFF' + headers.join(','),
      ...rows.map(r => [
        r.受注データID ? r.受注データID.substring(0, 8) : '',
        r.チャネル名 || '',
        r.検証ステータス || '',
        r.信頼度スコア || 0,
        r.エラーコード || '',
        r.修正優先度 || '',
        r.対応状況 || ''
      ].map(v => `"${String(v).replace(/"/g, '""')}"`).join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `validation_report_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  });

  // 7. 詳細ボタン
  container.addEventListener('click', async e => {
    const detailBtn = e.target.closest('.detail-btn');
    if (detailBtn) {
      const resultId = detailBtn.dataset.id;
      // 詳細確認・修正画面へ遷移
      window.showScreen('scr-1781413282852');
    }
  });

  // 初期ロード
  loadData();
}

function(container, apiUrl, tables) {
  // テーブルインデックス: 信頼度スコア = 0
  const tableIndex = 0;
  const tbody = container.querySelector("#result-tbody");
  const noResults = container.querySelector("#no-results");
