  });

  // 再描画関数
  function renderRows(rows) {
    if (!rows || rows.length === 0) {
      tbody.innerHTML = "";
      noResults.style.display = "block";
      resultCount.textContent = "0";
      return;
    }

    noResults.style.display = "none";
    resultCount.textContent = rows.length;

    tbody.innerHTML = rows.map(r => {
      const totalScore = r.総合スコア || r.total_score || 0;
      const completenessScore = r.完全性スコア || r.completeness_score || 0;
      const accuracyScore = r.正確性スコア || r.accuracy_score || 0;
      const consistencyScore = r.一貫性スコア || r.consistency_score || 0;
      const channel = r.チャネル || r.channel || "—";
      const validationStatus = r.検証ステータス || r.validation_status || "—";
      const warningFlag = r.警告フラグ || r.warning_flag || false;
      const orderId = r.受注ID || r.order_id || r.id || "—";
      const customerName = r.顧客名 || r.customer_name || "—";

      // スコアに応じた背景色（バッジ）
      const scoreColor = totalScore >= 80 ? "#2d5a2d" : totalScore >= 50 ? "#4a4a2d" : "#5a2d2d";
      const scoreTextColor = totalScore >= 80 ? "#a8e6a8" : totalScore >= 50 ? "#e6d9a8" : "#e6a8a8";

      // 警告バッジ
      const warningBadge = warningFlag 
        ? `<span style="display: inline-block; padding: 4px 8px; border-radius: 3px; background: #8b0000; color: #ffb3b3; font-size: 11px; font-weight: 600;">警告</span>`
        : `<span style="display: inline-block; padding: 4px 8px; border-radius: 3px; background: rgba(255,255,255,0.08); color: var(--text-muted); font-size: 11px;">—</span>`;

      return `
        <tr data-id="${r.id || ''}" style="border-bottom: 1px solid var(--border); transition: background 0.15s;">
          <td style="padding: 10px 12px; color: var(--text);">${orderId}</td>
          <td style="padding: 10px 12px; color: var(--text);">${customerName}</td>
          <td style="padding: 10px 12px; text-align: center; color: ${scoreTextColor}; background: ${scoreColor}; font-weight: 600;">${totalScore}</td>
          <td style="padding: 10px 12px; text-align: center; color: var(--text);">${completenessScore}</td>
          <td style="padding: 10px 12px; text-align: center; color: var(--text);">${accuracyScore}</td>
          <td style="padding: 10px 12px; text-align: center; color: var(--text);">${consistencyScore}</td>
          <td style="padding: 10px 12px; text-align: center; color: var(--text);">${channel}</td>
          <td style="padding: 10px 12px; text-align: center; color: var(--text);">${validationStatus}</td>
          <td style="padding: 10px 12px; text-align: center;">${warningBadge}</td>
          <td style="padding: 10px 12px; text-align: center;">
            <button class="action-btn secondary detail-btn" data-id="${r.id || ''}" style="padding: 4px 10px; font-size: 12px;">詳細</button>
          </td>
        </tr>
      `;
    }).join("");
  }

  // 初期データ表示
  renderRows(tables[tableIndex]?.records || []);

  // フィルタリング・検索ロジック
  function applyFilters() {
    const minScore = parseInt(container.querySelector("#min-score").value) || 0;
    const maxScore = parseInt(container.querySelector("#max-score").value) || 100;
    const confidenceLevel = container.querySelector("#confidence-level").value;
    const orderId = container.querySelector("#order-id-search").value.toLowerCase();
    const customerName = container.querySelector("#customer-name-search").value.toLowerCase();
    const channel = container.querySelector("#channel-filter").value;
    const validationStatus = container.querySelector("#validation-status-filter").value;
    const correctionHistory = container.querySelector("#correction-history-filter").value;
    const ocrConfidence = container.querySelector("#ocr-confidence-filter").value;
    const duplicateDetection = container.querySelector("#duplicate-detection-filter").value;
    const channelDiscrepancy = container.querySelector("#channel-discrepancy-filter").value;

    window.aivicApi.list(tableIndex).then(rows => {
      if (!rows) rows = tables[tableIndex]?.records || [];

      const filtered = rows.filter(r => {
        const totalScore = r.総合スコア || r.total_score || 0;
        const rOrderId = (r.受注ID || r.order_id || "").toLowerCase();
        const rCustomerName = (r.顧客名 || r.customer_name || "").toLowerCase();
        const rChannel = r.チャネル || r.channel || "";
        const rValidationStatus = r.検証ステータス || r.validation_status || "";
        const rCorrectionHistory = r.修正履歴有無 || r.correction_history || "無";
        const rOcrConfidence = r.AI_OCR信頼度 || r.ocr_confidence || 0;
        const rDuplicateDetection = r.重複検出 || r.duplicate_detection || "未検出";
        const rChannelDiscrepancy = r.チャネル間矛盾 || r.channel_discrepancy || "未検出";

        // スコア範囲フィルタ
        if (totalScore < minScore || totalScore > maxScore) return false;

        // 信頼度レベルフィルタ
        if (confidenceLevel) {
          if (confidenceLevel === "high" && totalScore < 80) return false;
          if (confidenceLevel === "medium" && (totalScore < 50 || totalScore >= 80)) return false;
          if (confidenceLevel === "low" && totalScore >= 50) return false;
        }

        // テキスト検索
        if (orderId && !rOrderId.includes(orderId)) return false;
        if (customerName && !rCustomerName.includes(customerName)) return false;

        // ドロップダウンフィルタ
        if (channel && rChannel !== channel) return false;
        if (validationStatus && rValidationStatus !== validationStatus) return false;
        if (correctionHistory && rCorrectionHistory !== correctionHistory) return false;
        if (duplicateDetection && rDuplicateDetection !== duplicateDetection) return false;
        if (channelDiscrepancy && rChannelDiscrepancy !== channelDiscrepancy) return false;

        // OCR信頼度フィルタ
        if (ocrConfidence) {
          if (ocrConfidence === "high" && rOcrConfidence < 80) return false;
          if (ocrConfidence === "medium" && (rOcrConfidence < 50 || rOcrConfidence >= 80)) return false;
          if (ocrConfidence === "low" && rOcrConfidence >= 50) return false;
        }

        return true;
      });

      renderRows(filtered);
    });
  }

  // 検索ボタン
  container.querySelector("#btn-search").addEventListener("click", applyFilters);

  // リセットボタン
  container.querySelector("#btn-reset").addEventListener("click", () => {
    container.querySelector("#score-slider").value = 0;
    container.querySelector("#score-display").textContent = "0";
    container.querySelector("#min-score").value = "0";
    container.querySelector("#max-score").value = "100";
    container.querySelector("#confidence-level").value = "";
    container.querySelector("#order-id-search").value = "";
    container.querySelector("#customer-name-search").value = "";
    container.querySelector("#channel-filter").value = "";
    container.querySelector("#validation-status-filter").value = "";
    container.querySelector("#correction-history-filter").value = "";
    container.querySelector("#ocr-confidence-filter").value = "";
    container.querySelector("#duplicate-detection-filter").value = "";
    container.querySelector("#channel-discrepancy-filter").value = "";
    renderRows(tables[tableIndex]?.records || []);
  });

  // CSVエクスポート
  container.querySelector("#btn-export-csv").addEventListener("click", () => {
    window.aivicApi.list(tableIndex).then(rows => {
      if (!rows) rows = tables[tableIndex]?.records || [];

      const headers = ["受注ID", "顧客名", "総合スコア", "完全性スコア", "正確性スコア", "一貫性スコア", "チャネル", "検証ステータス", "警告フラグ"];
      const csvContent = [
        "\uFEFF" + headers.map(h => `"${h}"`).join(","),
        ...rows.map(r => [
          r.受注ID || r.order_id || "",
          r.顧客名 || r.customer_name || "",
          r.総合スコア || r.total_score || 0,
          r.完全性スコア || r.completeness_score || 0,
          r.正確性スコア || r.accuracy_score || 0,
          r.一貫性スコア || r.consistency_score || 0,
          r.チャネル || r.channel || "",
          r.検証ステータス || r.validation_status || "",
          r.警告フラグ || r.warning_flag || false
        ].map(v => `"${String(v).replace(/"/g, '""')}"`).join(","))
      ].join("\n");

      const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
      const link = document.createElement("a");
      link.href = URL.createObjectURL(blob);
      link.download = "trust_score_export.csv";
      link.click();
    });
  });

  // ダッシュボードボタン
  container.querySelector("#btn-detail-dashboard").addEventListener("click", () => {
    window.showScreen("scr-1781413262699");
  });

  // 詳細ボタン（イベントデリゲーション）
  container.addEventListener("click", e => {
    const detailBtn = e.target.closest(".detail-btn");
    if (detailBtn) {
      const recordId = detailBtn.dataset.id;
      window.showScreen("scr-1781413282852", { recordId });
    }
  });
}

function(container, apiUrl, tables) {
  // ============================================
  // 1. 状態管理
  // ============================================
  let currentGuidanceStep = 2;
  let currentImageData = null;
  let currentOCRResult = null;
  let extractedFields = {};
  let ocrProgress = 0;

  // ============================================
  // 2. ガイダンス再生制御
  // ============================================
  const guidanceSteps = [
    "ステップ 1/5: 受注書を用意してください",
    "ステップ 2/5: 受注金額を入力してください",
    "ステップ 3/5: 顧客情報を確認してください",
    "ステップ 4/5: 配送先住所を確認してください",
    "ステップ 5/5: 内容を確認して確定してください"
  ];

  function updateGuidanceDisplay() {
    const stepEl = container.querySelector('[data-testid="guidance-step"]');
    if (stepEl) {
      stepEl.textContent = guidanceSteps[currentGuidanceStep - 1] || "ガイダンス完了";
    }
  }

  container.querySelector('[data-testid="btn-play-guidance"]').addEventListener('click', () => {
    // 音声ガイダンス再生シミュレーション
    const msg = new SpeechSynthesisUtterance(guidanceSteps[currentGuidanceStep - 1]);
    msg.lang = 'ja-JP';
    msg.rate = 1.0;
    const volumeSlider = container.querySelector('[data-testid="volume-slider"]');
    msg.volume = volumeSlider.value / 100;
    window.speechSynthesis.speak(msg);
  });

  container.querySelector('[data-testid="btn-pause-guidance"]').addEventListener('click', () => {
    window.speechSynthesis.cancel();
  });

  container.querySelector('[data-testid="volume-slider"]').addEventListener('input', (e) => {
    const percentEl = e.target.parentElement.querySelector('div:last-child');
    if (percentEl) {
      percentEl.textContent = e.target.value + '%';
    }
  });

  // ============================================
  // 3. カメラ/スキャナ操作
  // ============================================
  container.querySelector('[data-testid="btn-camera"]').addEventListener('click', () => {
    // カメラ起動シミュレーション
    const input = document.createElement('input');
    input.type = 'file';
    input.accept = 'image/*';
    input.onchange = (e) => {
      const file = e.target.files[0];
      if (file) {
        const reader = new FileReader();
        reader.onload = (evt) => {
          currentImageData = evt.target.result;
          const preview = container.querySelector('[data-testid="image-preview"]');
          preview.innerHTML = `<img src="${currentImageData}" style="max-width: 100%; max-height: 100%; object-fit: contain;">`;
        };
        reader.readAsDataURL(file);
      }
    };
    input.click();
  });

  container.querySelector('[data-testid="btn-scanner"]').addEventListener('click', () => {
    alert('スキャナ機能は別途デバイス連携が必要です');
  });

  // ============================================
  // 4. OCR処理シミュレーション
  // ============================================
  function simulateOCRProcessing() {
    ocrProgress = 0;
    const progressBar = container.querySelector('[data-testid="ocr-progress-bar"]');
    const progressPercent = container.querySelector('[data-testid="ocr-progress-percent"]');

    const interval = setInterval(() => {
      ocrProgress += Math.random() * 25;
      if (ocrProgress > 100) ocrProgress = 100;

      progressBar.style.width = ocrProgress + '%';
      progressPercent.textContent = Math.floor(ocrProgress) + '%';

      if (ocrProgress >= 100) {
        clearInterval(interval);
        displayOCRResults();
      }
    }, 300);
  }

  function displayOCRResults() {
    // サンプルOCR結果
    extractedFields = {
      customer_name: { value: '株式会社テスト', confidence: 95 },
      order_amount: { value: '¥150,000', confidence: 87 },
      order_date: { value: '2025-01-15', confidence: 92 },
      delivery_address: { value: '東京都渋谷区1-2-3', confidence: 78 },
      phone_number: { value: '03-XXXX-XXXX', confidence: 65 },
      product_name: { value: 'サンプル商品A', confidence: 88 }
    };

    // 総合スコア計算
    const scores = Object.values(extractedFields).map(f => f.confidence);
    const overallScore = Math.round(scores.reduce((a, b) => a + b, 0) / scores.length);

    container.querySelector('[data-testid="overall-confidence"]').textContent = overallScore + '%';
    container.querySelector('[data-testid="completeness-score"]').textContent = Math.round(overallScore * 0.95);
    container.querySelector('[data-testid="accuracy-score"]').textContent = Math.round(overallScore * 0.92);
    container.querySelector('[data-testid="consistency-score"]').textContent = Math.round(overallScore * 0.88);

    // 抽出データ表示
    const dataList = container.querySelector('[data-testid="extracted-data-list"]');
    dataList.innerHTML = Object.entries(extractedFields).map(([key, data]) => {
      const confidenceClass = data.confidence < 75 ? 'style="background: rgba(255,100,100,0.1); border-left: 2px solid #ff6464;"' : '';
      return `
        <div ${confidenceClass} style="padding: 6px; margin-bottom: 4px; border-radius: 2px;">
          <div style="font-size: 10px; color: var(--text-muted); margin-bottom: 1px;">${key}</div>
          <div style="font-size: 11px; color: var(--text); font-weight: 500;">${data.value}</div>
          <div style="font-size: 9px; color: var(--text-muted);">信頼度: ${data.confidence}%</div>
        </div>
      `;
    }).join('');

    // 低信頼度項目ハイライト
    const lowConfidenceItems = Object.entries(extractedFields)
      .filter(([_, data]) => data.confidence < 75)
      .map(([key, data]) => `<div style="padding: 4px 0; color: #ff9999;">• ${key}: ${data.confidence}%</div>`)
      .join('');

    const lowConfidenceEl = container.querySelector('[data-testid="low-confidence-items"]');
    if (lowConfidenceItems) {
      lowConfidenceEl.innerHTML = lowConfidenceItems;
    } else {
      lowConfidenceEl.innerHTML = '<div style="color: var(--text-muted); padding: 8px 0;">低信頼度項目はありません</div>';
    }
  }

  container.querySelector('[data-testid="btn-start-ocr"]').addEventListener('click', () => {
    if (!currentImageData) {
      alert('先に画像を撮影またはスキャンしてください');
      return;
    }
    simulateOCRProcessing();
  });

  // ============================================
  // 5. 手動修正
  // ============================================
  container.querySelector('[data-testid="btn-apply-correction"]').addEventListener('click', () => {
    const field = container.querySelector('[data-testid="correction-field"]').value;
    const value = container.querySelector('[data-testid="correction-value"]').value;

    if (!field || !value) {
      alert('修正項目と修正値を入力してください');
      return;
    }

    if (extractedFields[field]) {
      extractedFields[field].value = value;
      extractedFields[field].confidence = 100; // 手動修正は信頼度100%

      // 再表示
      displayOCRResults();

      // フォームクリア
      container.querySelector('[data-testid="correction-field"]').value = '';
      container.querySelector('[data-testid="correction-value"]').value = '';
    }
  });

  // ============================================
  // 6. 確定・クリア
  // ============================================
  container.querySelector('[data-testid="btn-confirm-data"]').addEventListener('click', async () => {
    if (Object.keys(extractedFields).length === 0) {
      alert('確定するデータがありません');
      return;
    }

    // AI_OCR読み込み結果テーブルに保存（tableIndex=3と仮定）
    const ocrResultData = {
      order_id: 'order-' + Date.now(),
      source_document_type: 'order_form',
      ocr_engine_version: '1.0.0',
      raw_ocr_text: JSON.stringify(extractedFields),
      extracted_fields: JSON.stringify(extractedFields),
      overall_confidence: Math.round(
        Object.values(extractedFields).reduce((a, b) => a + b.confidence, 0) / Object.keys(extractedFields).length
      ),
      processing_status: 'success',
      requires_manual_review: false
    };

    const saved = await window.aivicApi.save(3, ocrResultData);
    if (saved) {
      alert('データを確定しました。次の画面へ遷移します。');
      // 詳細確認画面へ遷移
      window.showScreen('scr-1781413282852');
    }
  });

  container.querySelector('[data-testid="btn-clear-data"]').addEventListener('click', () => {
    if (confirm('すべてのデータをクリアしますか？')) {
      currentImageData = null;
      currentOCRResult = null;
      extractedFields = {};
      ocrProgress = 0;

      container.querySelector('[data-testid="image-preview"]').innerHTML = '画像がまだ撮影されていません';
      container.querySelector('[data-testid="ocr-progress-bar"]').style.width = '0%';
      container.querySelector('[data-testid="ocr-progress-percent"]').textContent = '0%';
      container.querySelector('[data-testid="overall-confidence"]').textContent = '—';
      container.querySelector('[data-testid="completeness-score"]').textContent = '—';
      container.querySelector('[data-testid="accuracy-score"]').textContent = '—';
      container.querySelector('[data-testid="consistency-score"]').textContent = '—';
      container.querySelector('[data-testid="extracted-data-list"]').innerHTML = '<div style="color: var(--text-muted); text-align: center; padding: 20px 0;">データがまだ抽出されていません</div>';
      container.querySelector('[data-testid="low-confidence-items"]').innerHTML = '<div style="color: var(--text-muted); padding: 8px 0;">低信頼度項目はありません</div>';
    }
  });

  // ============================================
  // 7. 初期化
  // ============================================
  updateGuidanceDisplay();
}

function(container, apiUrl, tables) {
  const tbody = container.querySelector("#records-tbody");
  const detailPanel = container.querySelector("#detail-panel");
  const scoreMinInput = container.querySelector("#score-min");
  const scoreMaxInput = container.querySelector("#score-max");
  const channelFilter = container.querySelector("#channel-filter");
  const statusFilter = container.querySelector("#status-filter");
  const orderIdSearch = container.querySelector("#order-id-search");
  const btnSearch = container.querySelector("#btn-search");
  const btnReset = container.querySelector("#btn-reset");
  const btnExport = container.querySelector("#btn-export");
  const btnCloseDetail = container.querySelector("#btn-close-detail");
  const btnDetailEdit = container.querySelector("#btn-detail-edit");
  const btnDetailVerify = container.querySelector("#btn-detail-verify");
  const statusTotal = container.querySelector("#status-total");
  const statusFiltered = container.querySelector("#status-filtered");
  const statusMessage = container.querySelector("#status-message");

  let allRecords = [];
  let filteredRecords = [];
  let selectedRecord = null;

  // テーブルインデックス（信頼度スコアテーブルを想定）
  const tableIndex = 0;

  // 1. 再描画関数
  function renderRows(rows) {
    tbody.innerHTML = rows.map(r => {
      const scoreClass = r.総合スコア >= 80 ? 'pass' : r.総合スコア >= 60 ? 'warning' : 'fail';
      const scoreColor = r.総合スコア >= 80 ? 'var(--primary)' : r.総合スコア >= 60 ? '#ff9800' : '#f44336';
      return `
        <tr data-id="${r.受注データID || r.id}" style="border-bottom: 1px solid var(--border); cursor: pointer; transition: background 0.2s;" onmouseover="this.style.background='rgba(0,0,0,0.1)'" onmouseout="this.style.background='transparent'">
          <td style="padding: 10px 12px; color: var(--text); font-size: 12px; word-break: break-all;">${(r.受注データID || r.id || '').substring(0, 8)}</td>
          <td style="padding: 10px 12px; color: ${scoreColor}; font-weight: 600; font-size: 13px;">${r.総合スコア || '—'}</td>
          <td style="padding: 10px 12px; color: var(--text); font-size: 12px;">${r.完全性スコア || '—'}</td>
          <td style="padding: 10px 12px; color: var(--text); font-size: 12px;">${r.正確性スコア || '—'}</td>
          <td style="padding: 10px 12px; color: var(--text); font-size: 12px;">${r.一貫性スコア || '—'}</td>
          <td style="padding: 10px 12px; color: var(--text); font-size: 12px;">${r.チャネル || '—'}</td>
          <td style="padding: 10px 12px; color: var(--text); font-size: 12px;">
            <span style="display: inline-block; padding: 2px 6px; border-radius: 3px; background: ${r.検証ステータス === '合格' ? 'rgba(76,175,80,0.2)' : r.検証ステータス === '不合格' ? 'rgba(244,67,54,0.2)' : 'rgba(255,152,0,0.2)'}; color: ${r.検証ステータス === '合格' ? '#4caf50' : r.検証ステータス === '不合格' ? '#f44336' : '#ff9800'}; font-size: 11px; font-weight: 500;">
              ${r.検証ステータス || '—'}
            </span>
          </td>
          <td style="padding: 10px 12px; text-align: center; color: var(--text); font-size: 12px;">
            ${r.警告フラグ ? '<span style="color: #f44336; font-weight: 600;">⚠</span>' : '—'}
          </td>
          <td style="padding: 10px 12px; text-align: center;">
            <button class="view-detail-btn" data-id="${r.受注データID || r.id}" style="background: transparent; border: none; color: var(--primary); cursor: pointer; font-size: 12px; padding: 4px 8px; border-radius: 3px; transition: background 0.2s;" onmouseover="this.style.background='rgba(0,0,0,0.1)'" onmouseout="this.style.background='transparent';">詳細</button>
          </td>
        </tr>
      `;
    }).join("");

    statusTotal.textContent = `合計: ${allRecords.length}件`;
    statusFiltered.textContent = `表示: ${rows.length}件`;
  }

  // 2. 初期データ読み込み
  window.aivicApi.list(tableIndex).then(rows => {
    allRecords = rows || tables[tableIndex]?.records || [];
    filteredRecords = [...allRecords];
    renderRows(filteredRecords);
  });

  // 3. 検索ボタン
  btnSearch.addEventListener("click", () => {
    const minScore = parseInt(scoreMinInput.value) || 0;
    const maxScore = parseInt(scoreMaxInput.value) || 100;
    const channel = channelFilter.value;
    const status = statusFilter.value;
    const orderId = orderIdSearch.value.toLowerCase();

    filteredRecords = allRecords.filter(r => {
      const score = r.総合スコア || 0;
      const ch = (r.チャネル || '').toUpperCase();
      const st = r.検証ステータス || '';
      const oid = (r.受注データID || r.id || '').toLowerCase();

      return (
        score >= minScore &&
        score <= maxScore &&
        (!channel || ch === channel) &&
        (!status || st === status) &&
        (!orderId || oid.includes(orderId))
      );
    });

    renderRows(filteredRecords);
    statusMessage.textContent = `検索完了: ${filteredRecords.length}件`;
  });

  // 4. リセットボタン
  btnReset.addEventListener("click", () => {
    scoreMinInput.value = "";
    scoreMaxInput.value = "";
    channelFilter.value = "";
    statusFilter.value = "";
    orderIdSearch.value = "";
    filteredRecords = [...allRecords];
    renderRows(filteredRecords);
    statusMessage.textContent = "リセット完了";
  });

  // 5. CSVエクスポート
  btnExport.addEventListener("click", () => {
    const headers = ["受注ID", "総合スコア", "完全性", "正確性", "一貫性", "チャネル", "検証ステータス", "警告"];
    const rows = filteredRecords.map(r => [
      r.受注データID || r.id || '',
      r.総合スコア || '',
      r.完全性スコア || '',
      r.正確性スコア || '',
      r.一貫性スコア || '',
      r.チャネル || '',
      r.検証ステータス || '',
      r.警告フラグ ? '○' : ''
    ]);

    const csv = [
      '\uFEFF' + headers.map(h => `"${h}"`).join(','),
      ...rows.map(r => r.map(v => `"${v}"`).join(','))
    ].join('\n');

    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `信頼度スコア_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
    statusMessage.textContent = "CSVをダウンロードしました";
  });

  // 6. 詳細パネルを開く
  function showDetail(recordId) {
    selectedRecord = allRecords.find(r => r.受注データID === recordId || r.id === recordId);
    if (!selectedRecord) return;

    container.querySelector("#detail-order-id").textContent = recordId.substring(0, 12) + '...';
    container.querySelector("#detail-total-score").textContent = selectedRecord.総合スコア || '—';
    container.querySelector("#detail-completeness").textContent = selectedRecord.完全性スコア || '—';
    container.querySelector("#detail-accuracy").textContent = selectedRecord.正確性スコア || '—';
    container.querySelector("#detail-consistency").textContent = selectedRecord.一貫性スコア || '—';
    container.querySelector("#detail-warning-level").textContent = selectedRecord.警告レベル || '—';
    container.querySelector("#detail-channel").textContent = selectedRecord.チャネル || '—';
    container.querySelector("#detail-status").textContent = selectedRecord.検証ステータス || '—';
    container.querySelector("#detail-ocr-confidence").textContent = (selectedRecord.OCR信頼度 || '—') + '%';
    container.querySelector("#detail-ocr-status").textContent = selectedRecord.OCR処理ステータス || '—';
    container.querySelector("#detail-duplicate-count").textContent = (selectedRecord.重複検出数 || 0) + '件';
    container.querySelector("#detail-contradiction-count").textContent = (selectedRecord.矛盾検出数 || 0) + '件';
    container.querySelector("#detail-missing-count").textContent = (selectedRecord.入力漏れ検出数 || 0) + '件';

    // スコアバーの幅を更新
    const scoreBar = container.querySelector("#detail-total-score").parentElement.querySelector("div > div");
    scoreBar.style.width = (selectedRecord.総合スコア || 0) + '%';

    detailPanel.style.display = "flex";
  }

  // 7. 詳細パネルを閉じる
  btnCloseDetail.addEventListener("click", () => {
    detailPanel.style.display = "none";
    selectedRecord = null;
  });

  // 8. 詳細パネルのボタン
  btnDetailEdit.addEventListener("click", () => {
    if (selectedRecord) {
      window.showScreen("scr-1781413282852"); // 受注データ詳細確認・修正画面
    }
  });

  btnDetailVerify.addEventListener("click", () => {
    if (selectedRecord) {
      statusMessage.textContent = "再検証を実行中...";
      setTimeout(() => {
        statusMessage.textContent = "再検証が完了しました";
      }, 1500);
    }
  });

  // 9. 行クリックで詳細表示
  container.addEventListener("click", e => {
    const viewBtn = e.target.closest(".view-detail-btn");
    if (viewBtn) {
      showDetail(viewBtn.dataset.id);
    }
  });
}

