        <div style="font-size: 0.875rem; color: var(--text); background: rgba(255,0,0,0.1); padding: 0.375rem; border-radius: 0.25rem; border-left: 2px solid #ef4444; word-break: break-word;">${errorMsg}</div>
      </div>

      <div style="border-bottom: 1px solid rgba(255,255,255,0.08); padding: 0.5rem 0;">
        <div style="font-size: 0.75rem; color: var(--text-muted); margin-bottom: 0.25rem;">対応状況</div>
        <div style="font-size: 0.875rem; color: var(--text);">${correctionStatus}</div>
      </div>

      <div style="padding: 0.5rem 0;">
        <button data-testid="view-detail-button" class="action-btn" style="width: 100%; padding: 0.375rem; font-size: 0.875rem;">
          詳細確認・修正
        </button>
      </div>
    `;

    container.querySelector("[data-testid='view-detail-button']").addEventListener("click", () => {
      window.showScreen("scr-1781413282852");
    });
  }

  // フィルタリング
  function applyFilters() {
    const status = statusFilter.value;
    const channel = channelFilter.value;
    const severity = severityFilter.value;
    const scoreMin = parseInt(scoreMinInput.value) || 0;

    const filtered = allRows.filter(r => {
      if (status && r.validation_status !== status) return false;
      if (channel && r.channel !== channel) return false;
      if (severity && r.severity !== severity) return false;
      if ((r.confidence_score || 0) < scoreMin) return false;
      return true;
    });

    renderRows(filtered);
  }

  // 初期データ読み込み
  window.aivicApi.list(0).then(rows => {
    allRows = rows || tables[0].records || [];
    renderRows(allRows);
  });

  // 検索ボタン
  searchBtn.addEventListener("click", applyFilters);

  // フィルター変更時
  statusFilter.addEventListener("change", applyFilters);
  channelFilter.addEventListener("change", applyFilters);
  severityFilter.addEventListener("change", applyFilters);
  scoreMinInput.addEventListener("change", applyFilters);

  // 行クリックで詳細表示
  tbody.addEventListener("click", e => {
    const tr = e.target.closest("tr");
    if (tr) {
      const id = tr.dataset.id;
      const row = allRows.find(r => r.id === id);
      if (row) showDetail(row);
    }
  });

  // 自動検証実行
  autoValidateBtn.addEventListener("click", async () => {
    autoValidateBtn.disabled = true;
    autoValidateBtn.textContent = "検証中...";
    try {
      await new Promise(resolve => setTimeout(resolve, 2000));
      const updated = await window.aivicApi.list(0);
      allRows = updated || allRows;
      renderRows(allRows);
      alert("自動検証が完了しました");
    } finally {
      autoValidateBtn.disabled = false;
      autoValidateBtn.textContent = "自動検証実行";
    }
  });

  // CSV出力
  exportCsvBtn.addEventListener("click", () => {
    const headers = ["受注ID", "ステータス", "重要度", "エラーコード", "検証項目", "信頼度スコア", "エラーメッセージ"];
    const rows = allRows.map(r => [
      r.order_id || "",
      r.validation_status || "",
      r.severity || "",
      r.error_code || "",
      r.validation_item || "",
      r.confidence_score || 0,
      r.error_message || ""
    ]);
    const csv = "\uFEFF" + [headers, ...rows].map(row => 
      row.map(cell => `"${String(cell).replace(/"/g, '""')}"`).join(",")
    ).join("\n");
    const blob = new Blob([csv], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = "validation_results.csv";
    link.click();
  });

  // ナビゲーション
  viewDashboardBtn.addEventListener("click", () => window.showScreen("scr-1781413262699"));
  viewDuplicatesBtn.addEventListener("click", () => window.showScreen("scr-1781413297335"));
  viewChannelConflictsBtn.addEventListener("click", () => window.showScreen("scr-1781413311177"));
  viewMissingFieldsBtn.addEventListener("click", () => window.showScreen("scr-1781413340116"));
  viewPriorityListBtn.addEventListener("click", () => window.showScreen("scr-1781413354977"));
  viewApprovalFlowBtn.addEventListener("click", () => window.showScreen("scr-1781413369295"));
}

function(container, apiUrl, tables) {
  // ============================================
  // 1. データ取得・集計関数
  // ============================================
  async function fetchAndAggregate(filters = {}) {
    const validationResults = await window.aivicApi.list(0); // 受注データ検証結果
    const trustScores = await window.aivicApi.list(2); // 信頼度スコア
    const channels = await window.aivicApi.list(5); // チャネル情報

    if (!validationResults) return null;

    // フィルタリング
    let filtered = validationResults;
    if (filters.channel) {
      filtered = filtered.filter(r => r.チャネルID === filters.channel);
    }
    if (filters.status) {
      filtered = filtered.filter(r => r.検証ステータス === filters.status);
    }
    if (filters.startDate || filters.endDate) {
      filtered = filtered.filter(r => {
        const date = new Date(r.検証実行日時);
        if (filters.startDate && date < new Date(filters.startDate)) return false;
        if (filters.endDate && date > new Date(filters.endDate)) return false;
        return true;
      });
    }

    // 集計
    const stats = {
      totalOrders: new Set(filtered.map(r => r.受注データID)).size,
      errorCount: filtered.filter(r => r.検証ステータス === '不合格').length,
      warningCount: filtered.filter(r => r.検証ステータス === '警告').length,
      fixedCount: filtered.filter(r => r.対応状況 === '完了').length,
      pendingCount: filtered.filter(r => r.対応状況 === '保留').length,
      statusBreakdown: {},
      channelErrorRate: {},
      avgScore: 0
    };

    // ステータス別集計
    ['合格', '不合格', '警告', '保留'].forEach(status => {
      const items = filtered.filter(r => r.検証ステータス === status);
      stats.statusBreakdown[status] = {
        count: items.length,
        percentage: stats.totalOrders > 0 ? ((items.length / stats.totalOrders) * 100).toFixed(1) : 0,
        avgScore: items.length > 0 
          ? (items.reduce((sum, r) => {
              const score = trustScores?.find(s => s.受注データID === r.受注データID);
              return sum + (score?.総合スコア || 0);
            }, 0) / items.length).toFixed(1)
          : 0
      };
    });

    // チャネル別エラー率
    if (channels) {
      channels.forEach(ch => {
        const chFiltered = filtered.filter(r => r.チャネルID === ch.チャネルID);
        const errors = chFiltered.filter(r => r.検証ステータス === '不合格').length;
        stats.channelErrorRate[ch.チャネル名] = chFiltered.length > 0 
          ? ((errors / chFiltered.length) * 100).toFixed(1)
          : 0;
      });
    }

    // 平均信頼度スコア
    if (trustScores && trustScores.length > 0) {
      const scores = trustScores.filter(s => 
        filtered.some(r => r.受注データID === s.受注データID)
      );
      stats.avgScore = scores.length > 0
        ? (scores.reduce((sum, s) => sum + (s.総合スコア || 0), 0) / scores.length).toFixed(1)
        : 0;
    }

    return stats;
  }

  // ============================================
  // 2. KPI カード更新
  // ============================================
  function updateKPIs(stats) {
    container.querySelector('[data-testid="kpi-total-orders"]').textContent = stats.totalOrders;
    container.querySelector('[data-testid="kpi-error-count"]').textContent = stats.errorCount;
    container.querySelector('[data-testid="kpi-warning-count"]').textContent = stats.warningCount;
    container.querySelector('[data-testid="kpi-fixed-count"]').textContent = stats.fixedCount;
    container.querySelector('[data-testid="kpi-pending-count"]').textContent = stats.pendingCount;
    container.querySelector('[data-testid="kpi-avg-score"]').textContent = stats.avgScore;
  }

  // ============================================
  // 3. ステータス別集計テーブル更新
  // ============================================
  function updateStatusTable(stats) {
    const tbody = container.querySelector('#status-summary-tbody');
    const rows = Object.entries(stats.statusBreakdown).map(([status, data]) => `
      <tr style="border-bottom: 1px solid rgba(255,255,255,0.04);">
        <td style="padding: 8px; color: var(--text);">${status}</td>
        <td style="padding: 8px; text-align: right; color: var(--text);">${data.count}</td>
        <td style="padding: 8px; text-align: right; color: var(--text-muted);">${data.percentage}%</td>
        <td style="padding: 8px; text-align: right; color: var(--text);">${data.avgScore}</td>
      </tr>
    `).join('');
    tbody.innerHTML = rows || '<tr><td colspan="4" style="padding: 12px; text-align: center; color: var(--text-muted);">データなし</td></tr>';
  }

  // ============================================
  // 4. チャネル別エラー率グラフ（棒グラフ）
  // ============================================
  function drawChannelErrorChart(stats) {
    const canvas = container.querySelector('#chart-channel-error');
    const ctx = canvas.getContext('2d');
    const channels = Object.keys(stats.channelErrorRate);
    const rates = Object.values(stats.channelErrorRate).map(r => parseFloat(r));

    if (channels.length === 0) {
      ctx.fillStyle = '#9fb0d1';
      ctx.font = '12px sans-serif';
      ctx.fillText('データなし', 10, 90);
      return;
    }

    const padding = 40;
    const chartWidth = canvas.width - padding * 2;
    const chartHeight = canvas.height - padding * 2;
    const barWidth = chartWidth / (channels.length * 1.5);
    const maxRate = Math.max(...rates, 100);

    // 背景
    ctx.fillStyle = 'rgba(0,0,0,0.1)';
    ctx.fillRect(padding, padding, chartWidth, chartHeight);

    // Y軸ラベル
    ctx.fillStyle = '#9fb0d1';
    ctx.font = '10px sans-serif';
    ctx.textAlign = 'right';
    for (let i = 0; i <= 5; i++) {
      const y = padding + chartHeight - (chartHeight / 5) * i;
      const val = (maxRate / 5) * i;
      ctx.fillText(val.toFixed(0) + '%', padding - 5, y + 3);
      ctx.strokeStyle = 'rgba(255,255,255,0.05)';
      ctx.beginPath();
      ctx.moveTo(padding, y);
      ctx.lineTo(canvas.width - padding, y);
      ctx.stroke();
    }

    // 棒
    ctx.textAlign = 'center';
    rates.forEach((rate, i) => {
      const x = padding + (i + 0.5) * (chartWidth / channels.length);
      const barHeight = (rate / maxRate) * chartHeight;
      const y = padding + chartHeight - barHeight;

      ctx.fillStyle = '#ff9800';
      ctx.fillRect(x - barWidth / 2, y, barWidth, barHeight);

      // ラベル
      ctx.fillStyle = '#9fb0d1';
      ctx.font = '10px sans-serif';
      ctx.fillText(channels[i], x, canvas.height - 10);
      ctx.fillText(rate.toFixed(1) + '%', x, y - 5);
    });
  }

  // ============================================
  // 5. 検証結果内訳円グラフ
  // ============================================
  function drawValidationPieChart(stats) {
    const canvas = container.querySelector('#chart-validation-pie');
    const ctx = canvas.getContext('2d');
    const breakdown = stats.statusBreakdown;
    const labels = Object.keys(breakdown);
    const values = Object.values(breakdown).map(d => d.count);
    const total = values.reduce((a, b) => a + b, 0);

    if (total === 0) {
      ctx.fillStyle = '#9fb0d1';
      ctx.font = '12px sans-serif';
      ctx.fillText('データなし', canvas.width / 2 - 30, canvas.height / 2);
      return;
    }

    const colors = ['#4caf50', '#f44336', '#ff9800', '#2196f3'];
    const centerX = canvas.width / 2;
    const centerY = canvas.height / 2;
    const radius = Math.min(canvas.width, canvas.height) / 2 - 30;
    let currentAngle = -Math.PI / 2;

    values.forEach((val, i) => {
      const sliceAngle = (val / total) * Math.PI * 2;
      ctx.fillStyle = colors[i] || '#999';
      ctx.beginPath();
      ctx.moveTo(centerX, centerY);
      ctx.arc(centerX, centerY, radius, currentAngle, currentAngle + sliceAngle);
      ctx.closePath();
      ctx.fill();

      // ラベル
      const labelAngle = currentAngle + sliceAngle / 2;
      const labelX = centerX + Math.cos(labelAngle) * (radius * 0.7);
      const labelY = centerY + Math.sin(labelAngle) * (radius * 0.7);
      ctx.fillStyle = '#fff';
      ctx.font = 'bold 11px sans-serif';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      const percentage = ((val / total) * 100).toFixed(0);
      ctx.fillText(percentage + '%', labelX, labelY);

      currentAngle += sliceAngle;
    });

    // 凡例
    ctx.font = '10px sans-serif';
    ctx.textAlign = 'left';
    labels.forEach((label, i) => {
      ctx.fillStyle = colors[i] || '#999';
      ctx.fillRect(10, canvas.height - 60 + i * 15, 10, 10);
      ctx.fillStyle = '#9fb0d1';
      ctx.fillText(label + ' (' + values[i] + ')', 25, canvas.height - 55 + i * 15);
    });
  }

  // ============================================
  // 6. 初期化・イベントリスナー
  // ============================================
  async function initialize() {
    const stats = await fetchAndAggregate();
    if (stats) {
      updateKPIs(stats);
      updateStatusTable(stats);
      drawChannelErrorChart(stats);
      drawValidationPieChart(stats);
    }
  }

  // 集計ボタン
  container.querySelector('[data-testid="filter-apply-btn"]').addEventListener('click', async () => {
    const startDate = container.querySelector('[data-testid="period-start"]').value;
    const endDate = container.querySelector('[data-testid="period-end"]').value;
    const channel = container.querySelector('[data-testid="channel-filter"]').value;
    const status = container.querySelector('[data-testid="status-filter"]').value;

    const stats = await fetchAndAggregate({
      startDate,
      endDate,
      channel,
      status
    });
    if (stats) {
      updateKPIs(stats);
      updateStatusTable(stats);
      drawChannelErrorChart(stats);
      drawValidationPieChart(stats);
    }
  });

  // CSVエクスポート
  container.querySelector('[data-testid="export-csv-btn"]').addEventListener('click', async () => {
    const validationResults = await window.aivicApi.list(0);
    if (!validationResults || validationResults.length === 0) {
      alert('エクスポートするデータがありません');
      return;
    }

    const headers = ['検証結果ID', '受注データID', '検証ステータス', 'エラーコード', '重要度', '検証実行日時', '対応状況'];
    const rows = validationResults.map(r => [
      r.検証結果ID || '',
      r.受注データID || '',
      r.検証ステータス || '',
      r.エラーコード || '',
      r.重要度 || '',
      r.検証実行日時 || '',
      r.対応状況 || ''
    ]);

    const csv = '\uFEFF' + headers.join(',') + '\n' + rows.map(r => r.map(v => `"${String(v).replace(/"/g, '""')}"`).join(',')).join('\n');
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = 'validation_summary_' + new Date().toISOString().split('T')[0] + '.csv';
    link.click();
  });

  // 詳細ダッシュボード遷移
  container.querySelector('[data-testid="detail-dashboard-btn"]').addEventListener('click', () => {
    window.showScreen('scr-1781413262699');
  });

  // 検証レポート遷移
  container.querySelector('[data-testid="validation-report-btn"]').addEventListener('click', () => {
    window.showScreen('scr-1781413382983');
  });

  initialize();
}

function(container, apiUrl, tables) {
  const tbody = container.querySelector("#result-tbody");
  const detailPanel = container.querySelector("#detail-panel");
  const filterOrderId = container.querySelector("#filter-order-id");
  const filterStatus = container.querySelector("#filter-status");
  const filterConfidence = container.querySelector("#filter-confidence");
  const filterSeverity = container.querySelector("#filter-severity");

  let allRows = [];
  let selectedRowId = null;

  // ステータスバッジ色
  function getStatusBadgeStyle(status) {
    const colors = {
      "合格": "#10b981",
      "不合格": "#ef4444",
      "警告": "#f59e0b",
      "保留": "#6b7280"
    };
    return colors[status] || "#9ca3af";
  }

  // 重要度色
  function getSeverityColor(severity) {
    const colors = {
      "致命的": "#dc2626",
      "高": "#f97316",
      "中": "#eab308",
      "低": "#84cc16"
    };
    return colors[severity] || "#9ca3af";
  }

  // 一覧再描画
  function renderRows(rows) {
    tbody.innerHTML = rows.map(r => {
      const statusColor = getStatusBadgeStyle(r.検証ステータス || "保留");
      const severityColor = getSeverityColor(r.重要度 || "低");
      const score = r.総合スコア || 0;
      return `
        <tr data-id="${r.検証結果ID || r.id}" style="border-bottom: 1px solid rgba(255,255,255,0.05); cursor: pointer; transition: background 0.2s;" onmouseover="this.style.background='rgba(255,255,255,0.05)'" onmouseout="this.style.background='transparent'">
          <td style="padding: 8px 12px; color: var(--text); font-weight: 500;">${r.受注データID ? r.受注データID.substring(0, 8) : "-"}</td>
