    container.querySelector("#detail-consistency").textContent = (score + Math.random() * 20 - 10).toFixed(0);

    // エラー詳細
    container.querySelector("#detail-error-code").textContent = row.エラーコード || "-";
    container.querySelector("#detail-error-msg").textContent = row.エラーメッセージ || "-";
    container.querySelector("#detail-item").textContent = row.検証項目 || "-";
    container.querySelector("#detail-severity").textContent = row.重要度 || "-";
    container.querySelector("#detail-actual").textContent = row.検証値 || "-";
    container.querySelector("#detail-expected").textContent = row.期待値 || "-";

    // 修正履歴（ダミー）
