      <div style="background: rgba(255,255,255,0.05); padding: 6px; border-radius: 3px; border-left: 2px solid var(--primary);">
        <div style="display: flex; justify-content: space-between; margin-bottom: 2px;">
          <span style="color: var(--text); font-weight: 500;">受注金額</span>
          <span style="color: var(--text-muted);">2024-01-15 14:30</span>
        </div>
        <div style="color: var(--text-muted); font-size: 10px;">修正前: 100,000 → 修正後: 105,000</div>
      </div>
    `;
    container.querySelector("#detail-history").innerHTML = historyHtml;

