      <div style="background: rgba(255,255,255,0.05); padding: 6px; border-radius: 3px;">
        <div style="display: flex; justify-content: space-between; margin-bottom: 2px;">
          <span style="color: var(--text); font-weight: 500;">品質確認</span>
          <span style="color: #10b981; font-weight: 600;">承認</span>
        </div>
        <div style="color: var(--text-muted); font-size: 10px;">確認者: 田中太郎 | 2024-01-15 15:00</div>
      </div>
    `;
    container.querySelector("#detail-approvals").innerHTML = approvalsHtml;

    detailPanel.style.display = "block";
  }

  // 初期データ描画
  renderRows(tables[0]?.records || []);
  allRows = tables[0]?.records || [];

  // 行クリック
  tbody.addEventListener("click", e => {
    const tr = e.target.closest("tr");
    if (tr) {
      const rowId = tr.dataset.id;
      const row = allRows.find(r => (r.検証結果ID || r.id) === rowId);
      if (row) showDetail(row);
    }
  });

  // 詳細パネル閉じる
  container.querySelector("#btn-close-detail").addEventListener("click", () => {
    detailPanel.style.display = "none";
  });

  // 検索
  container.querySelector("#btn-search").addEventListener("click", async () => {
    const orderId = filterOrderId.value.toLowerCase();
    const status = filterStatus.value;
    const confidence = filterConfidence.value;
    const severity = filterSeverity.value;

    let filtered = allRows;

    if (orderId) {
      filtered = filtered.filter(r => (r.受注データID || "").toLowerCase().includes(orderId));
    }
    if (status) {
      filtered = filtered.filter(r => r.検証ステータス === status);
    }
    if (confidence) {
      const [min, max] = confidence.split("-").map(Number);
      filtered = filtered.filter(r => {
        const score = r.総合スコア || 0;
        return score >= min && score <= max;
      });
    }
    if (severity) {
      filtered = filtered.filter(r => r.重要度 === severity);
    }

    renderRows(filtered);
  });

  // CSVエクスポート
  container.querySelector("#btn-export").addEventListener("click", async () => {
    const rows = tbody.querySelectorAll("tr");
    const headers = ["受注ID", "ステータス", "信頼度", "エラーコード", "重要度", "検証日時"];
    const csvRows = [headers.join(",")];

    rows.forEach(tr => {
      const cells = tr.querySelectorAll("td");
      const row = [
        cells[0].textContent,
        cells[1].textContent.trim(),
        cells[2].textContent,
        cells[3].textContent,
        cells[4].textContent.trim(),
        cells[5].textContent
      ];
      csvRows.push(row.map(c => `"${c.replace(/"/g, '""')}"`).join(","));
    });

    const csv = "\uFEFF" + csvRows.join("\n");
    const blob = new Blob([csv], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = "order-validation-results.csv";
    link.click();
  });

  // 優先度リスト画面へ遷移
  container.querySelector("#btn-priority-list").addEventListener("click", () => {
    window.showScreen("scr-1781413354977");
  });

  // データ修正画面へ遷移
  container.querySelector("#btn-edit-data").addEventListener("click", () => {
    if (selectedRowId) {
      window.showScreen("scr-1781413282852");
    } else {
      alert("修正対象を選択してください");
    }
  });
}

function(container, apiUrl, tables) {
  const orderTbody = container.querySelector("#order-tbody");
  const detailPanel = container.querySelector("#detail-panel");
  const noSelection = container.querySelector("#no-selection");
  const approvalForm = container.querySelector("#approval-form");
  const noApprovalForm = container.querySelector("#no-approval-form");
  const successMsg = container.querySelector("#success-message");
  const errorMsg = container.querySelector("#error-message");

  let selectedOrderId = null;
  let allOrders = [];

  // 1. テーブル再描画関数
  function renderOrders(orders) {
    orderTbody.innerHTML = orders.map(order => {
      const statusColor = order.検証ステータス === "不合格" ? "#ff6b6b" : 
                         order.検証ステータス === "警告" ? "#ffa94d" : "#4dabf7";
      return `
        <tr data-id="${order.id || order.受注ID}" style="cursor: pointer; border-bottom: 1px solid rgba(255,255,255,0.1); transition: background 0.2s;">
          <td style="padding: 8px; color: var(--text);">${order.受注ID || "-"}</td>
          <td style="padding: 8px; color: var(--text);">${order.顧客名 || "-"}</td>
          <td style="padding: 8px; text-align: right; color: var(--text);">¥${(order.受注金額 || 0).toLocaleString()}</td>
          <td style="padding: 8px; text-align: center;">
            <span style="display: inline-block; padding: 3px 6px; border-radius: 3px; font-size: 10px; font-weight: 600; background: rgba(${statusColor === "#ff6b6b" ? "255,107,107" : statusColor === "#ffa94d" ? "255,164,77" : "77,171,247"},0.2); color: ${statusColor};">
              ${order.検証ステータス || "-"}
            </span>
          </td>
          <td style="padding: 8px; text-align: center; color: var(--text); font-weight: 600;">${order.信頼度スコア || 0}</td>
        </tr>
      `;
    }).join("");
  }

  // 2. 初期データ描画
  if (tables[0] && tables[0].records) {
    allOrders = tables[0].records;
    renderOrders(allOrders);
  }

  // 3. 検索ボタン
  container.querySelector("[data-testid='search-button']").addEventListener("click", async () => {
    const statusFilter = container.querySelector("[data-testid='status-filter']").value;
    const confidenceMin = parseInt(container.querySelector("[data-testid='confidence-min']").value) || 0;
    const dateFrom = container.querySelector("[data-testid='order-date-from']").value;

    const filtered = allOrders.filter(order => {
      if (statusFilter && order.検証ステータス !== statusFilter) return false;
      if (order.信頼度スコア < confidenceMin) return false;
      if (dateFrom && new Date(order.受注日時) < new Date(dateFrom)) return false;
      return true;
    });

    renderOrders(filtered);
  });

  // 4. 行クリックで詳細表示
  container.addEventListener("click", (e) => {
    const row = e.target.closest("tr[data-id]");
    if (!row) return;

    selectedOrderId = row.dataset.id;
    const order = allOrders.find(o => (o.id || o.受注ID) === selectedOrderId);
    if (!order) return;

    // 詳細パネル表示
    noSelection.style.display = "none";
    detailPanel.style.display = "flex";

    container.querySelector("#detail-order-id").textContent = order.受注ID || "-";
    container.querySelector("#detail-customer").textContent = order.顧客名 || "-";
    container.querySelector("#detail-amount").textContent = `¥${(order.受注金額 || 0).toLocaleString()}`;
    container.querySelector("#detail-channel").textContent = order.チャネル || "-";
    container.querySelector("#detail-status").textContent = order.検証ステータス || "-";
    container.querySelector("#detail-score").textContent = `${order.信頼度スコア || 0}`;

    // 問題一覧（検証結果から）
    const issues = order.検出された問題 ? order.検出された問題.split("\n").filter(x => x) : [];
    container.querySelector("#detail-issues").innerHTML = issues.length > 0 
      ? issues.map(i => `<div>• ${i}</div>`).join("")
      : "<div style='color: var(--text-muted);'>なし</div>";

    // 入力漏れ項目
    const missing = order.入力漏れ項目 ? order.入力漏れ項目.split("\n").filter(x => x) : [];
    container.querySelector("#detail-missing").innerHTML = missing.length > 0
      ? missing.map(m => `<div>• ${m}</div>`).join("")
      : "<div style='color: var(--text-muted);'>なし</div>";

    // チャネル間矛盾
    const conflicts = order.チャネル間矛盾内容 ? order.チャネル間矛盾内容.split("\n").filter(x => x) : [];
    container.querySelector("#detail-conflicts").innerHTML = conflicts.length > 0
      ? conflicts.map(c => `<div>• ${c}</div>`).join("")
      : "<div style='color: var(--text-muted);'>なし</div>";

    // 承認フォーム表示
    noApprovalForm.style.display = "none";
    approvalForm.style.display = "flex";
    container.querySelector("[data-testid='approval-decision']").value = "";
    container.querySelector("[data-testid='approval-reason']").value = "";

    // 行のハイライト
    container.querySelectorAll("tbody tr").forEach(tr => tr.style.background = "");
    row.style.background = "rgba(77,171,247,0.1)";
  });

  // 5. 承認ボタン
  container.querySelector("[data-testid='approve-button']").addEventListener("click", async () => {
    const decision = container.querySelector("[data-testid='approval-decision']").value;
    const reason = container.querySelector("[data-testid='approval-reason']").value;

    if (!decision) {
      errorMsg.textContent = "判定を選択してください";
      errorMsg.style.display = "block";
      setTimeout(() => errorMsg.style.display = "none", 3000);
      return;
    }

    if (!reason.trim()) {
      errorMsg.textContent = "判定理由を入力してください";
      errorMsg.style.display = "block";
      setTimeout(() => errorMsg.style.display = "none", 3000);
      return;
    }

    // 承認フロー記録を保存（テーブルインデックス 1 と仮定）
    const approvalData = {
      受注データID: selectedOrderId,
      判定結果: decision,
      判定理由: reason,
      判定日時: new Date().toISOString()
    };

    const saved = await window.aivicApi.save(1, approvalData);
    if (saved) {
      successMsg.textContent = `受注 ${selectedOrderId} を「${decision}」で承認しました`;
      successMsg.style.display = "block";
      setTimeout(() => successMsg.style.display = "none", 3000);

      // フォームリセット
      selectedOrderId = null;
      noSelection.style.display = "block";
      detailPanel.style.display = "none";
      noApprovalForm.style.display = "block";
      approvalForm.style.display = "none";
      container.querySelectorAll("tbody tr").forEach(tr => tr.style.background = "");
    }
  });

  // 6. 差戻しボタン
  container.querySelector("[data-testid='reject-button']").addEventListener("click", async () => {
    const reason = container.querySelector("[data-testid='approval-reason']").value;

    if (!reason.trim()) {
      errorMsg.textContent = "差戻し理由を入力してください";
      errorMsg.style.display = "block";
      setTimeout(() => errorMsg.style.display = "none", 3000);
      return;
    }

    const approvalData = {
      受注データID: selectedOrderId,
      判定結果: "差戻し",
      判定理由: reason,
      判定日時: new Date().toISOString()
    };

    const saved = await window.aivicApi.save(1, approvalData);
    if (saved) {
      successMsg.textContent = `受注 ${selectedOrderId} を差戻ししました`;
      successMsg.style.display = "block";
      setTimeout(() => successMsg.style.display = "none", 3000);

      selectedOrderId = null;
      noSelection.style.display = "block";
      detailPanel.style.display = "none";
      noApprovalForm.style.display = "block";
      approvalForm.style.display = "none";
      container.querySelectorAll("tbody tr").forEach(tr => tr.style.background = "");
    }
  });
}

function(container, apiUrl, tables) {
  const errorTbody = container.querySelector("#error-tbody");
  const listCount = container.querySelector("#list-count");
  const detailPanel = container.querySelector("#detail-panel");
  const noSelection = container.querySelector("#no-selection");

  let allErrors = [];
  let selectedErrorId = null;

  // 1. 再描画関数
  function renderErrorList(errors) {
    errorTbody.innerHTML = errors.map((err, idx) => `
      <tr data-id="${err.id || idx}" style="border-bottom: 1px solid rgba(255,255,255,0.08); cursor: pointer; transition: background 0.2s;" onmouseover="this.style.background='rgba(255,255,255,0.04)'" onmouseout="this.style.background=''">
        <td style="padding: 10px 12px; display: block;">
          <div style="display: flex; justify-content: space-between; align-items: start; gap: 8px;">
            <div style="flex: 1;">
              <div style="font-size: 12px; font-weight: 600; color: var(--text); margin-bottom: 2px;">
                ${err.検証項目 || err.漏れ項目名 || '不明'}
              </div>
              <div style="font-size: 11px; color: var(--text-muted); margin-bottom: 4px;">
                受注ID: ${(err.受注データID || err.受注ID || '').substring(0, 8)}...
              </div>
              <div style="display: flex; gap: 6px; flex-wrap: wrap;">
                <span style="background: ${err.重要度 === '致命的' ? 'rgba(255,100,100,0.2)' : err.重要度 === '高' ? 'rgba(255,150,100,0.2)' : 'rgba(100,150,255,0.2)'}; color: var(--text); padding: 2px 6px; border-radius: 3px; font-size: 10px; font-weight: 500;">
                  ${err.重要度 || '不明'}
                </span>
                <span style="background: rgba(100,200,150,0.2); color: var(--text); padding: 2px 6px; border-radius: 3px; font-size: 10px;">
                  ${err.検証ステータス || err.検出ステータス || '未対応'}
                </span>
              </div>
            </div>
            <div style="text-align: right; flex-shrink: 0;">
              <div style="font-size: 11px; color: var(--text-muted);">信頼度</div>
              <div style="font-size: 13px; font-weight: 600; color: var(--primary);">${err.信頼度スコア || err.マッチング信頼度 || 0}%</div>
            </div>
          </div>
        </td>
      </tr>
    `).join("");
    listCount.textContent = `${errors.length}件`;
  }

  // 2. 詳細パネル表示関数
  function showDetail(error) {
    selectedErrorId = error.id;
    container.querySelector("#detail-order-id").textContent = error.受注データID || error.受注ID || '-';
    container.querySelector("#detail-status").textContent = error.検証ステータス || error.検出ステータス || '-';
    container.querySelector("#detail-item").textContent = error.検証項目 || error.漏れ項目名 || '-';
    container.querySelector("#detail-severity").textContent = error.重要度 || '-';
    container.querySelector("#detail-message").textContent = error.エラーメッセージ || error.矛盾内容 || '-';
    container.querySelector("#detail-actual").textContent = error.検証値 || error.マッチング理由 || '-';
    container.querySelector("#detail-expected").textContent = error.期待値 || '-';

    // フォームをクリア
    container.querySelector("#correction-item").value = error.検証項目 || error.漏れ項目名 || '';
    container.querySelector("#correction-before").value = error.検証値 || '';
    container.querySelector("#correction-after").value = '';
    container.querySelector("#correction-reason").value = '';
    container.querySelector("#correction-note").value = '';

    detailPanel.style.display = 'block';
    noSelection.style.display = 'none';
  }

  // 3. 初期データ読み込み
  async function loadErrors() {
    try {
      const validationResults = await window.aivicApi.list(0); // 受注データ検証結果
      const duplicateResults = await window.aivicApi.list(1);  // 重複受注検出結果
      const channelConflicts = await window.aivicApi.list(2);  // チャネル間矛盾検出結果
      const missingInputs = await window.aivicApi.list(3);     // 入力漏れ検出結果

      allErrors = [
        ...(validationResults || []),
        ...(duplicateResults || []),
        ...(channelConflicts || []),
        ...(missingInputs || [])
      ].sort((a, b) => {
        const severityOrder = { '致命的': 0, '高': 1, '中': 2, '低': 3 };
        const aSev = severityOrder[a.重要度] !== undefined ? severityOrder[a.重要度] : 4;
        const bSev = severityOrder[b.重要度] !== undefined ? severityOrder[b.重要度] : 4;
        return aSev - bSev;
      });

      renderErrorList(allErrors);
    } catch (e) {
      console.error("データ読み込みエラー:", e);
    }
  }

  // 4. フィルタリング関数
  function applyFilters() {
    const statusFilter = container.querySelector("[data-testid='status-filter']").value;
    const severityFilter = container.querySelector("[data-testid='severity-filter']").value;
    const errorTypeFilter = container.querySelector("[data-testid='error-type-filter']").value;
    const confidenceMin = parseInt(container.querySelector("[data-testid='confidence-min']").value) || 0;

    let filtered = allErrors.filter(err => {
      if (statusFilter && (err.検証ステータス || err.検出ステータス) !== statusFilter) return false;
      if (severityFilter && err.重要度 !== severityFilter) return false;
      if (errorTypeFilter) {
        const errorType = err.エラーコード || err.マッチング理由 || '';
        if (!errorType.includes(errorTypeFilter)) return false;
      }
      const confidence = err.信頼度スコア || err.マッチング信頼度 || 0;
      if (confidence < confidenceMin) return false;
      return true;
    });

    renderErrorList(filtered);
  }

  // 5. 検索ボタン
  container.querySelector("[data-testid='search-button']").addEventListener("click", applyFilters);

  // 6. CSVエクスポート
  container.querySelector("[data-testid='export-button']").addEventListener("click", () => {
    if (allErrors.length === 0) {
      alert("エクスポートするデータがありません");
      return;
    }
    const headers = ["受注ID", "検証項目", "検証ステータス", "重要度", "エラーメッセージ", "信頼度スコア"];
    const rows = allErrors.map(err => [
      err.受注データID || err.受注ID || '',
      err.検証項目 || err.漏れ項目名 || '',
      err.検証ステータス || err.検出ステータス || '',
      err.重要度 || '',
      err.エラーメッセージ || '',
      err.信頼度スコア || err.マッチング信頼度 || ''
    ]);
    const csv = '\uFEFF' + [headers, ...rows].map(r => r.map(v => `"${String(v).replace(/"/g, '""')}"`).join(',')).join('\n');
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `errors_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  });

  // 7. 行クリックで詳細表示
  container.addEventListener("click", (e) => {
    const row = e.target.closest("tr");
    if (row) {
      const rowId = row.dataset.id;
      const error = allErrors.find(err => (err.id || allErrors.indexOf(err)) == rowId);
      if (error) showDetail(error);
    }
  });

  // 8. 修正確認ボタン
  container.querySelector("[data-testid='confirm-button']").addEventListener("click", async () => {
    const item = container.querySelector("[data-testid='correction-item']").value;
    const before = container.querySelector("[data-testid='correction-before']").value;
    const after = container.querySelector("[data-testid='correction-after']").value;
    const reason = container.querySelector("[data-testid='correction-reason']").value;
    const note = container.querySelector("[data-testid='correction-note']").value;

    if (!item || !after || !reason) {
      alert("必須項目を入力してください");
      return;
    }

    try {
      const correctionRecord = {
        受注データID: selectedErrorId,
        修正項目名: item,
        修正前値: before,
        修正後値: after,
        修正理由: reason,
        修正備考: note,
        修正ユーザーID: "current-user",
        修正日時: new Date().toISOString()
      };

      await window.aivicApi.save(4, correctionRecord); // 受注データ修正履歴テーブル
      alert("修正が確認されました");

      // リストをリロード
      await loadErrors();
      detailPanel.style.display = 'none';
      noSelection.style.display = 'flex';
    } catch (e) {
      console.error("修正保存エラー:", e);
      alert("修正の保存に失敗しました");
    }
  });

  // 9. 修正却下ボタン
  container.querySelector("[data-testid='reject-button']").addEventListener("click", () => {
    if (confirm("この修正を却下しますか？")) {
      detailPanel.style.display = 'none';
      noSelection.style.display = 'flex';
      alert("修正が却下されました");
    }
  });

  // 初期化
  loadErrors();
}

function(container, apiUrl, tables) {
  // テーブルインデックス
  const MODIFY_HISTORY_TABLE = 0;  // 受注データ修正履歴
  const VALIDATION_TABLE = 1;      // 受注データ検証結果
  const SCORE_TABLE = 2;           // 信頼度スコア
  const CHANNEL_TABLE = 3;         // チャネル情報

  // 現在の修正対象受注ID（URL パラメータまたはセッションから取得）
  let currentOrderId = new URLSearchParams(window.location.search).get('orderId') || 'sample-order-001';
  let currentModifyHistory = null;
  let currentValidationBefore = null;
  let currentValidationAfter = null;
  let currentScoreBefore = null;

  // ===== 1. 初期データ描画 =====
  async function initializeScreen() {
    // 修正対象の受注情報を取得（サンプルデータから）
    const histories = tables[MODIFY_HISTORY_TABLE]?.records || [];
    const validations = tables[VALIDATION_TABLE]?.records || [];
    const scores = tables[SCORE_TABLE]?.records || [];
    const channels = tables[CHANNEL_TABLE]?.records || [];

    // 現在の受注に関連する修正履歴を取得
    const orderHistories = histories.filter(h => h.受注データID === currentOrderId);
    if (orderHistories.length > 0) {
      currentModifyHistory = orderHistories[orderHistories.length - 1];
    }

    // 検証結果を取得
    const orderValidations = validations.filter(v => v.受注データID === currentOrderId);
    if (orderValidations.length > 0) {
      currentValidationBefore = orderValidations[orderValidations.length - 1];
    }

    // 信頼度スコアを取得
    const orderScores = scores.filter(s => s.受注データID === currentOrderId);
    if (orderScores.length > 0) {
      currentScoreBefore = orderScores[orderScores.length - 1];
    }

    // UI に情報を表示
    displayOrderInfo(currentModifyHistory, channels);
    displayDiffContent(currentModifyHistory);
    displayValidationResults(currentValidationBefore);
    displayScoreInfo(currentScoreBefore);
    displayModifyItems(currentModifyHistory);
    renderTimeline(orderHistories);
  }

  // ===== 2. 受注情報表示 =====
  function displayOrderInfo(history, channels) {
    const orderIdEl = container.querySelector('#order-id-display');
    const channelEl = container.querySelector('#channel-display');
    const modifierEl = container.querySelector('#modifier-display');
    const datetimeEl = container.querySelector('#modify-datetime-display');

    if (history) {
      orderIdEl.textContent = history.受注データID || '-';

      // チャネル情報を取得
      const channel = channels.find(c => c.チャネルID === history.チャネルID);
      channelEl.textContent = channel?.チャネル名 || '-';

      modifierEl.textContent = history.修正ユーザーID || '-';
      datetimeEl.textContent = history.修正日時 ? new Date(history.修正日時).toLocaleString('ja-JP') : '-';
    } else {
      orderIdEl.textContent = currentOrderId;
      channelEl.textContent = '-';
      modifierEl.textContent = '-';
      datetimeEl.textContent = '-';
    }
  }

  // ===== 3. 差分表示 =====
  function displayDiffContent(history) {
    const diffContainer = container.querySelector('#diff-container');
    diffContainer.innerHTML = '';

    if (!history) {
      diffContainer.innerHTML = '<div style="color: var(--text-muted); font-size: 12px;">差分データなし</div>';
      return;
    }

    const diffRow = document.createElement('div');
    diffRow.style.cssText = 'padding: 8px; background: rgba(255,165,0,0.08); border-left: 3px solid #ffa500; border-radius: 3px;';
    diffRow.innerHTML = `
      <div style="font-weight: 600; color: var(--text); margin-bottom: 4px;">${history.修正項目名 || '項目'}</div>
      <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 8px; font-size: 11px;">
        <div>
          <div style="color: var(--text-muted); margin-bottom: 2px;">修正前</div>
          <div style="color: var(--text); word-break: break-all; font-family: monospace;">${history.修正前値 || '-'}</div>
        </div>
        <div>
          <div style="color: var(--text-muted); margin-bottom: 2px;">修正後</div>
          <div style="color: var(--text); word-break: break-all; font-family: monospace;">${history.修正後値 || '-'}</div>
        </div>
      </div>
    `;
    diffContainer.appendChild(diffRow);
  }

  // ===== 4. 検証結果表示 =====
  function displayValidationResults(validation) {
    const beforeEl = container.querySelector('#validation-before');
    const afterEl = container.querySelector('#validation-after');

    if (validation) {
      beforeEl.textContent = validation.検証ステータス || '-';
      beforeEl.style.color = validation.検証ステータス === '合格' ? '#4ade80' : '#ef4444';
      afterEl.textContent = '検証待機中';
      afterEl.style.color = '#fbbf24';
    } else {
      beforeEl.textContent = '-';
      afterEl.textContent = '-';
    }
  }

  // ===== 5. 信頼度スコア表示 =====
  function displayScoreInfo(score) {
    const scoreBeforeEl = container.querySelector('#score-before');
    const scoreAfterEl = container.querySelector('#score-after');

    if (score) {
      scoreBeforeEl.textContent = `${score.総合スコア || 0}/100`;
      scoreAfterEl.value = score.総合スコア || 0;
    } else {
      scoreBeforeEl.textContent = '-';
      scoreAfterEl.value = '';
    }
  }

  // ===== 6. 修正項目一覧表示 =====
  function displayModifyItems(history) {
    const container_items = container.querySelector('#modify-items-container');
    container_items.innerHTML = '';

    if (!history) {
      container_items.innerHTML = '<div style="color: var(--text-muted); font-size: 12px;">修正項目なし</div>';
      return;
    }

    const item = document.createElement('div');
    item.style.cssText = 'padding: 6px; background: var(--bg-main); border-radius: 3px; border-left: 2px solid var(--primary);';
    item.innerHTML = `
      <div style="font-weight: 600; color: var(--text); margin-bottom: 2px;">${history.修正項目名 || '項目'}</div>
      <div style="color: var(--text-muted); font-size: 11px;">理由: ${history.修正理由 || '-'}</div>
    `;
    container_items.appendChild(item);
  }

  // ===== 7. タイムライン描画 =====
  function renderTimeline(histories) {
    const timelineContainer = container.querySelector('#timeline-container');
    timelineContainer.innerHTML = '';

    if (!histories || histories.length === 0) {
      timelineContainer.innerHTML = '<div style="color: var(--text-muted);">修正履歴がありません</div>';
      return;
    }

    histories.forEach((h, idx) => {
      const timelineItem = document.createElement('div');
      timelineItem.style.cssText = 'padding: 8px; margin-bottom: 8px; border-left: 2px solid var(--primary); padding-left: 12px;';
      timelineItem.innerHTML = `
        <div style="font-weight: 600; color: var(--text); font-size: 11px;">${h.修正項目名 || '項目'}</div>
        <div style="color: var(--text-muted); font-size: 10px; margin-top: 2px;">${h.修正日時 ? new Date(h.修正日時).toLocaleString('ja-JP') : '-'}</div>
        <div style="color: var(--text-muted); font-size: 10px;">理由: ${h.修正理由 || '-'}</div>
      `;
      timelineContainer.appendChild(timelineItem);
    });
  }

  // ===== 8. 保存処理 =====
  container.querySelector('#btn-save').addEventListener('click', async () => {
    const reasonCategory = container.querySelector('#reason-category').value;
    const modifyNotes = container.querySelector('#modify-notes').value;
    const scoreAfter = parseInt(container.querySelector('#score-after').value) || 0;
    const completenessScore = parseInt(container.querySelector('#completeness-score').value) || 0;
    const accuracyScore = parseInt(container.querySelector('#accuracy-score').value) || 0;
    const consistencyScore = parseInt(container.querySelector('#consistency-score').value) || 0;

    if (!reasonCategory) {
      alert('修正理由を選択してください');
      return;
    }

    // 修正履歴を保存
    const modifyHistoryData = {
      受注データID: currentOrderId,
      修正項目名: currentModifyHistory?.修正項目名 || '受注データ',
      修正前値: currentModifyHistory?.修正前値 || '',
      修正後値: currentModifyHistory?.修正後値 || '',
      修正理由: reasonCategory,
      修正備考: modifyNotes,
      修正ユーザーID: 'current-user-id',
      修正日時: new Date().toISOString(),
      検証結果ID: currentValidationBefore?.検証結果ID || null
    };

    const saved = await window.aivicApi.save(MODIFY_HISTORY_TABLE, modifyHistoryData);
    if (!saved) {
      alert('修正履歴の保存に失敗しました');
      return;
    }

    // 信頼度スコアを更新
    if (currentScoreBefore) {
      const scoreUpdateData = {
        総合スコア: scoreAfter,
        完全性スコア: completenessScore,
        正確性スコア: accuracyScore,
        一貫性スコア: consistencyScore,
        スコア計算日時: new Date().toISOString(),
        警告フラグ: scoreAfter < 60,
        警告レベル: scoreAfter < 40 ? '高' : scoreAfter < 60 ? '中' : '低'
      };
      await window.aivicApi.update(SCORE_TABLE, currentScoreBefore.信頼度スコアID, scoreUpdateData);
    }

    alert('修正履歴を保存しました');
    // 画面をリセット
    container.querySelector('#reason-category').value = '';
    container.querySelector('#modify-notes').value = '';
    container.querySelector('#score-after').value = '';
    container.querySelector('#completeness-score').value = '';
    container.querySelector('#accuracy-score').value = '';
    container.querySelector('#consistency-score').value = '';

    // 修正後の検証結果を「検証待機中」から「検証実行」に更新
    if (currentValidationBefore) {
      await window.aivicApi.update(VALIDATION_TABLE, currentValidationBefore.検証結果ID, {
        検証ステータス: '検証実行中'
      });
    }

    // 画面をリロード
    setTimeout(() => {
      window.location.reload();
    }, 1000);
  });

  // ===== 9. キャンセル処理 =====
  container.querySelector('#btn-cancel').addEventListener('click', () => {
    if (confirm('修正内容を破棄しますか？')) {
      container.querySelector('#reason-category').value = '';
      container.querySelector('#modify-notes').value = '';
      container.querySelector('#score-after').value = '';
      container.querySelector('#completeness-score').value = '';
      container.querySelector('#accuracy-score').value = '';
      container.querySelector('#consistency-score').value = '';
    }
  });

  // ===== 10. タイムラインの表示/非表示切り替え =====
  container.querySelector('#btn-toggle-timeline').addEventListener('click', () => {
    const timelineContainer = container.querySelector('#timeline-container');
    const toggleBtn = container.querySelector('#btn-toggle-timeline');
    if (timelineContainer.style.display === 'none') {
      timelineContainer.style.display = 'block';
      toggleBtn.textContent = '非表示';
    } else {
      timelineContainer.style.display = 'none';
      toggleBtn.textContent = '表示';
    }
  });

  // ===== 初期化実行 =====
  initializeScreen();
}

function(container, apiUrl, tables) {
  const tbody = container.querySelector("#records-tbody");
  const totalCountEl = container.querySelector("#total-count");
  let allRecords = [];

  // 1. テーブル再描画関数
  function renderRows(rows) {
    tbody.innerHTML = rows.map(r => {
      const statusColor = r.検証ステータス === "合格" ? "#4ade80" : 
                          r.検証ステータス === "不合格" ? "#ef4444" : 
                          r.検証ステータス === "警告" ? "#f59e0b" : "#6b7280";

      const scoreColor = (r.総合スコア || 0) >= 80 ? "#4ade80" : 
                         (r.総合スコア || 0) >= 60 ? "#f59e0b" : "#ef4444";

      return `
        <tr data-id="${r.id}" style="border-bottom: 1px solid rgba(255,255,255,0.06); cursor: pointer; transition: background 0.15s;" 
            onmouseover="this.style.background='rgba(255,255,255,0.04)'" 
            onmouseout="this.style.background='transparent'">
          <td style="padding: 8px 12px; color: var(--text); font-weight: 500;">${r.受注ID || "—"}</td>
          <td style="padding: 8px 12px; color: var(--text-muted); font-size: 11px;">${r.受注日時 ? new Date(r.受注日時).toLocaleString("ja-JP") : "—"}</td>
          <td style="padding: 8px 12px; color: var(--text);">${r.チャネル名 || "—"}</td>
          <td style="padding: 8px 12px;">
            <span style="display: inline-block; padding: 2px 6px; border-radius: 2px; background: ${statusColor}; color: #fff; font-size: 11px; font-weight: 500;">
              ${r.検証ステータス || "—"}
            </span>
          </td>
          <td style="padding: 8px 12px; text-align: center; color: ${scoreColor}; font-weight: 600;">
            ${r.総合スコア !== undefined ? r.総合スコア : "—"}
          </td>
          <td style="padding: 8px 12px; color: var(--text-muted); font-size: 11px;">
            ${r.エラーコード ? `<span style="color: #ef4444;">${r.エラーコード}</span>` : "正常"}
          </td>
          <td style="padding: 8px 12px; text-align: center;">
            <button class="action-btn secondary detail-btn" data-id="${r.id}" style="padding: 4px 8px; font-size: 11px;">
              詳細
            </button>
          </td>
        </tr>
      `;
    }).join("");
    totalCountEl.textContent = rows.length;
  }

  // 2. 初期データ表示
  if (tables[0] && tables[0].records) {
    allRecords = tables[0].records;
    renderRows(allRecords);
  }

  // 3. 検索ボタン
  container.querySelector("#btn-search").addEventListener("click", () => {
    const orderId = container.querySelector("#filter-order-id").value.toLowerCase();
    const dateFrom = container.querySelector("#filter-date-from").value;
    const dateTo = container.querySelector("#filter-date-to").value;
    const status = container.querySelector("#filter-status").value;
    const channel = container.querySelector("#filter-channel").value;
    const scoreMin = parseInt(container.querySelector("#filter-score-min").value) || 0;
    const scoreMax = parseInt(container.querySelector("#filter-score-max").value) || 100;
    const warning = container.querySelector("#filter-warning").value;

    const filtered = allRecords.filter(r => {
      if (orderId && !(r.受注ID || "").toLowerCase().includes(orderId)) return false;
      if (dateFrom && new Date(r.受注日時) < new Date(dateFrom)) return false;
      if (dateTo && new Date(r.受注日時) > new Date(dateTo + "T23:59:59")) return false;
      if (status && r.検証ステータス !== status) return false;
      if (channel && r.チャネル名 !== channel) return false;
      if ((r.総合スコア || 0) < scoreMin || (r.総合スコア || 0) > scoreMax) return false;
      if (warning === "true" && !r.警告フラグ) return false;
      if (warning === "false" && r.警告フラグ) return false;
      return true;
    });

    renderRows(filtered);
  });

  // 4. リセットボタン
  container.querySelector("#btn-reset").addEventListener("click", () => {
    container.querySelector("#filter-order-id").value = "";
    container.querySelector("#filter-date-from").value = "";
    container.querySelector("#filter-date-to").value = "";
    container.querySelector("#filter-status").value = "";
    container.querySelector("#filter-channel").value = "";
    container.querySelector("#filter-score-min").value = "";
    container.querySelector("#filter-score-max").value = "";
    container.querySelector("#filter-warning").value = "";
    renderRows(allRecords);
  });

  // 5. 詳細ボタン（行レベル操作）
  container.addEventListener("click", e => {
    const detailBtn = e.target.closest(".detail-btn");
    if (detailBtn) {
      const recordId = detailBtn.dataset.id;
      window.showScreen("scr-1781413282852", { recordId });
    }

    const dashboardBtn = e.target.closest("#btn-dashboard");
    if (dashboardBtn) {
      window.showScreen("scr-1781413262699");
    }
  });

  // 6. CSVエクスポート
  container.querySelector("#btn-export-csv").addEventListener("click", () => {
    if (allRecords.length === 0) {
      alert("エクスポートするデータがありません");
      return;
    }

    const headers = ["受注ID", "受注日時", "チャネル名", "検証ステータス", "総合スコア", "エラーコード", "重要度"];
    const rows = allRecords.map(r => [
      r.受注ID || "",
      r.受注日時 ? new Date(r.受注日時).toLocaleString("ja-JP") : "",
      r.チャネル名 || "",
      r.検証ステータス || "",
      r.総合スコア || "",
      r.エラーコード || "",
      r.重要度 || ""
    ]);

    const csv = [
      "\uFEFF" + headers.map(h => `"${h}"`).join(","),
      ...rows.map(row => row.map(cell => `"${String(cell).replace(/"/g, '""')}"`).join(","))
    ].join("\n");

    const blob = new Blob([csv], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `受注ステータス照会_${new Date().toISOString().split("T")[0]}.csv`;
    link.click();
  });
}

function(container, apiUrl, tables) {
  // テーブルインデックス（データ構造から推測）
  const orderTableIdx = 0;           // 受注データ
  const validationTableIdx = 1;      // 受注データ検証結果
  const ocrTableIdx = 2;             // AI_OCR読み込み結果
  const modificationTableIdx = 3;    // 受注データ修正履歴

  let allOrders = [];
  let selectedOrderId = null;

  // ===== 1. 受注一覧の再描画関数 =====
  function renderOrderList(orders) {
    const tbody = container.querySelector("#order-list-tbody");
    tbody.innerHTML = orders.map(order => `
      <tr 
        data-id="${order.id}" 
        class="order-row" 
        style="border-bottom: 1px solid var(--border); cursor: pointer; transition: background 0.15s;"
        onmouseover="this.style.background='rgba(255,255,255,0.05)'"
        onmouseout="this.style.background='transparent'"
      >
        <td style="padding: 8px; border-right: 1px solid var(--border); color: var(--text);">${order.id || ""}</td>
        <td style="padding: 8px; border-right: 1px solid var(--border); color: var(--text);">${order.customer_name || ""}</td>
        <td style="padding: 8px; color: var(--text-muted);">${order.order_date ? new Date(order.order_date).toLocaleDateString('ja-JP') : ""}</td>
      </tr>
    `).join("");
  }

  // ===== 2. 受注詳細フォームの読み込み =====
  function loadOrderDetail(orderId) {
    selectedOrderId = orderId;
    const order = allOrders.find(o => o.id === orderId);
    if (!order) return;

    container.querySelector("#form-order-id").value = order.id || "";
    container.querySelector("#form-channel").value = order.channel || "";
    container.querySelector("#form-order-date").value = order.order_date ? order.order_date.slice(0, 16) : "";
    container.querySelector("#form-customer-name").value = order.customer_name || "";
    container.querySelector("#form-product").value = order.product_name || "";
    container.querySelector("#form-quantity").value = order.quantity || "";
    container.querySelector("#form-amount").value = order.amount || "";
    container.querySelector("#form-address").value = order.shipping_address || "";
    container.querySelector("#form-shipping-method").value = order.shipping_method || "";
    container.querySelector("#form-notes").value = order.notes || "";

    // OCR結果の表示
    loadOCRResult(orderId);

    // 検証結果の表示
    loadValidationResult(orderId);
  }

  // ===== 3. OCR読み込み結果の表示 =====
  function loadOCRResult(orderId) {
    const ocrPanel = container.querySelector("#ocr-result-panel");
    if (!tables[ocrTableIdx] || !tables[ocrTableIdx].records) {
      ocrPanel.innerHTML = '<span style="color: var(--text-muted);">OCR結果なし</span>';
      return;
    }

    const ocrResult = tables[ocrTableIdx].records.find(r => r.order_id === orderId);
    if (!ocrResult) {
      ocrPanel.innerHTML = '<span style="color: var(--text-muted);">OCR結果なし</span>';
      return;
    }

    const confidenceColor = ocrResult.overall_confidence >= 80 ? '#4ade80' : ocrResult.overall_confidence >= 60 ? '#fbbf24' : '#ef4444';
    ocrPanel.innerHTML = `
      <div style="margin-bottom: 6px;">
        <strong>信頼度:</strong> <span style="color: ${confidenceColor}; font-weight: 600;">${ocrResult.overall_confidence}%</span>
      </div>
      <div style="margin-bottom: 6px;">
        <strong>ステータス:</strong> ${ocrResult.processing_status || ""}
      </div>
      <div style="font-size: 10px; color: var(--text-muted); word-break: break-all;">
        ${ocrResult.error_message ? `<strong>エラー:</strong> ${ocrResult.error_message}` : '<span style="color: #4ade80;">✓ 処理成功</span>'}
      </div>
    `;
  }

  // ===== 4. 検証結果の表示 =====
  function loadValidationResult(orderId) {
    const validationPanel = container.querySelector("#validation-result-panel");
    if (!tables[validationTableIdx] || !tables[validationTableIdx].records) {
      validationPanel.innerHTML = '<span style="color: var(--text-muted);">検証結果なし</span>';
      return;
    }

    const validationResults = tables[validationTableIdx].records.filter(r => r.order_data_id === orderId);
    if (validationResults.length === 0) {
      validationPanel.innerHTML = '<span style="color: #4ade80;">✓ 検証合格</span>';
      return;
    }

    const html = validationResults.map(v => {
      const severityColor = v.severity === "致命的" ? '#ef4444' : v.severity === "高" ? '#f97316' : v.severity === "中" ? '#fbbf24' : '#94a3b8';
      return `
        <div style="margin-bottom: 6px; padding: 6px; background: rgba(0,0,0,0.3); border-left: 3px solid ${severityColor}; border-radius: 2px;">
          <div style="font-weight: 600; color: var(--text);">${v.validation_item}</div>
          <div style="font-size: 10px; color: var(--text-muted);">${v.error_message || ""}</div>
          <div style="font-size: 10px; color: ${severityColor};">重要度: ${v.severity}</div>
        </div>
      `;
    }).join("");
    validationPanel.innerHTML = html;
  }

  // ===== 5. 初期データ読み込み =====
  window.aivicApi.list(orderTableIdx).then(orders => {
    allOrders = orders || [];
    renderOrderList(allOrders);
  });

  // ===== 6. 受注一覧の行クリック =====
  container.addEventListener("click", e => {
    const row = e.target.closest(".order-row");
    if (row) {
      const orderId = row.dataset.id;
      loadOrderDetail(orderId);
      // 選択行のハイライト
      container.querySelectorAll(".order-row").forEach(r => r.style.background = "transparent");
      row.style.background = "rgba(255,255,255,0.1)";
    }
  });

  // ===== 7. 検索ボタン =====
  container.querySelector("#btn-search-order").addEventListener("click", () => {
    const keyword = container.querySelector("#search-order-input").value.toLowerCase();
    const filtered = allOrders.filter(o => 
      (o.id && o.id.toLowerCase().includes(keyword)) ||
      (o.customer_name && o.customer_name.toLowerCase().includes(keyword))
    );
    renderOrderList(filtered);
  });

  // ===== 8. 保存ボタン =====
  container.querySelector("#btn-save-order").addEventListener("click", async () => {
    if (!selectedOrderId) {
      alert("受注を選択してください");
      return;
    }

    const updateData = {
      id: selectedOrderId,
      channel: container.querySelector("#form-channel").value,
      order_date: container.querySelector("#form-order-date").value,
      customer_name: container.querySelector("#form-customer-name").value,
      product_name: container.querySelector("#form-product").value,
      quantity: parseInt(container.querySelector("#form-quantity").value) || 0,
      amount: parseFloat(container.querySelector("#form-amount").value) || 0,
      shipping_address: container.querySelector("#form-address").value,
      shipping_method: container.querySelector("#form-shipping-method").value,
      notes: container.querySelector("#form-notes").value
    };

    const result = await window.aivicApi.update(orderTableIdx, selectedOrderId, updateData);
    if (result) {
      alert("受注を保存しました");
      // 修正履歴を記録
      await window.aivicApi.save(modificationTableIdx, {
        order_data_id: selectedOrderId,
        modification_item: "受注データ一括更新",
        modification_reason: "ユーザー修正",
        modification_user_id: "current-user",
        modification_date: new Date().toISOString()
      });
      // 一覧を再読み込み
      window.aivicApi.list(orderTableIdx).then(orders => {
        allOrders = orders || [];
        renderOrderList(allOrders);
      });
    }
  });

  // ===== 9. キャンセルボタン =====
  container.querySelector("#btn-cancel").addEventListener("click", () => {
    container.querySelectorAll("input, select, textarea").forEach(el => el.value = "");
    selectedOrderId = null;
    container.querySelector("#ocr-result-panel").innerHTML = '<span>受注を選択してください</span>';
    container.querySelector("#validation-result-panel").innerHTML = '<span>検証結果はここに表示されます</span>';
  });
}

function(container, apiUrl, tables) {
  // テーブルインデックス（データ構造から推測）
  const TABLE_VALIDATION = 0;      // 受注データ検証結果
  const TABLE_CORRECTION = 1;      // 受注データ修正履歴
  const TABLE_CONFIDENCE = 2;      // 信頼度スコア
  const TABLE_OCR = 3;             // AI_OCR読み込み結果
  const TABLE_VOICE = 4;           // 音声ガイダンス記録
  const TABLE_CHANNEL = 5;         // チャネル情報
  const TABLE_DUPLICATE = 6;       // 重複受注検出結果
  const TABLE_CONTRADICTION = 7;   // チャネル間矛盾検出結果
  const TABLE_MISSING = 8;         // 入力漏れ検出結果
  const TABLE_PRIORITY = 9;        // 修正対象優先度リスト

  // 現在の抽出データ
  let currentExtractedData = null;
  let currentConfidenceScore = null;

  // ===== 1. 優先度リスト再描画関数 =====
  function renderPriorityList(rows) {
    const tbody = container.querySelector("#priority-tbody");
    if (!rows || rows.length === 0) {
      tbody.innerHTML = '<tr><td colspan="5" style="padding: 12px; text-align: center; color: var(--text-muted);">修正対象がありません</td></tr>';
      return;
    }
    tbody.innerHTML = rows.map(r => `
      <tr style="border-bottom: 1px solid rgba(255,255,255,0.08);">
        <td style="padding: 6px 8px; color: var(--text);">
          <span style="display: inline-block; width: 20px; height: 20px; border-radius: 50%; background: ${getPriorityColor(r.優先度レベル)}; color: #fff; font-size: 10px; font-weight: 700; text-align: center; line-height: 20px;">
            ${r.優先度レベル || '—'}
          </span>
        </td>
        <td style="padding: 6px 8px; color: var(--text);">${r.エラー分類 || '—'}</td>
        <td style="padding: 6px 8px; color: var(--text);">
          <span style="padding: 2px 6px; border-radius: 3px; background: ${getStatusBg(r.修正ステータス)}; color: var(--text); font-size: 10px;">
            ${r.修正ステータス || '—'}
          </span>
        </td>
        <td style="padding: 6px 8px; color: var(--text);">${r.信頼度スコア || '—'}%</td>
        <td style="padding: 6px 8px; text-align: center;">
          <button class="action-btn secondary edit-priority-btn" data-id="${r.優先度リストID}" style="padding: 3px 8px; font-size: 10px;">
            編集
          </button>
        </td>
      </tr>
    `).join("");
  }

  function getPriorityColor(level) {
    const colors = { 1: '#ff4444', 2: '#ff8800', 3: '#ffbb00', 4: '#88cc00', 5: '#44aa44' };
    return colors[level] || '#888888';
  }

  function getStatusBg(status) {
    const bgMap = {
      '未対応': 'rgba(255,68,68,0.15)',
      '対応中': 'rgba(255,136,0,0.15)',
      '完了': 'rgba(68,170,68,0.15)',
      '保留': 'rgba(136,136,136,0.15)'
    };
    return bgMap[status] || 'rgba(136,136,136,0.15)';
  }

  // ===== 2. 初期データ読み込み =====
  window.aivicApi.list(TABLE_PRIORITY).then(rows => {
    renderPriorityList(rows || []);
  });

  // ===== 3. AI_OCR実行ボタン =====
  container.querySelector("#btn-ocr-exec").addEventListener("click", async () => {
    const channel = container.querySelector("#channel-select").value;
    const docType = container.querySelector("#doc-type-select").value;
    const orderData = container.querySelector("#order-data-input").value;

    if (!channel || !docType || !orderData) {
      alert("チャネル、ドキュメント種別、受注データを入力してください");
      return;
    }

    // OCR処理をシミュレート（実際にはAPI呼び出し）
    const ocrResult = {
      source_document_type: docType,
      raw_ocr_text: orderData,
      overall_confidence: Math.floor(Math.random() * 30) + 70, // 70-100
      processing_status: "成功",
      extracted_fields: {
        customer_name: "サンプル顧客",
        order_amount: "150000",
        order_date: new Date().toISOString().split('T')[0],
        items: ["商品A", "商品B"]
      }
    };

    currentExtractedData = ocrResult;
    currentConfidenceScore = ocrResult.overall_confidence;

    // プレビュー表示
    container.querySelector("#preview-container").textContent = JSON.stringify(ocrResult.extracted_fields, null, 2);

    // 信頼度スコア表示
    container.querySelector("#score-overall").textContent = ocrResult.overall_confidence;
    container.querySelector("#score-completeness").textContent = Math.floor(Math.random() * 20) + 80;
    container.querySelector("#score-accuracy").textContent = Math.floor(Math.random() * 20) + 75;
    container.querySelector("#score-consistency").textContent = Math.floor(Math.random() * 20) + 70;

    // 検証結果を自動生成
    simulateValidation();
  });

  // ===== 4. 検証シミュレーション =====
  function simulateValidation() {
    // 重複受注検出
    const hasDuplicate = Math.random() > 0.7;
    if (hasDuplicate) {
      container.querySelector("#duplicate-result").innerHTML = `
        <div style="padding: 6px; background: rgba(255,68,68,0.15); border-radius: 3px; color: #ff6b6b;">
          ⚠️ 重複の可能性あり<br/>
          <span style="font-size: 10px; color: var(--text-muted);">信頼度: 85%</span>
        </div>
      `;
    } else {
      container.querySelector("#duplicate-result").innerHTML = `
        <div style="padding: 6px; background: rgba(68,170,68,0.15); border-radius: 3px; color: #44aa44;">
          ✓ 重複なし
        </div>
      `;
    }

    // チャネル間矛盾検出
    const hasContradiction = Math.random() > 0.8;
    if (hasContradiction) {
      container.querySelector("#contradiction-result").innerHTML = `
        <div style="padding: 6px; background: rgba(255,136,0,0.15); border-radius: 3px; color: #ff8800;">
          ⚠️ 矛盾検出<br/>
          <span style="font-size: 10px; color: var(--text-muted);">金額相違</span>
        </div>
      `;
    } else {
      container.querySelector("#contradiction-result").innerHTML = `
        <div style="padding: 6px; background: rgba(68,170,68,0.15); border-radius: 3px; color: #44aa44;">
          ✓ 矛盾なし
        </div>
      `;
    }

    // 入力漏れ検出
    const missingItems = [];
    if (Math.random() > 0.6) missingItems.push("配送先住所");
    if (Math.random() > 0.7) missingItems.push("電話番号");

    if (missingItems.length > 0) {
      container.querySelector("#missing-result").innerHTML = `
        <div style="padding: 6px; background: rgba(255,136,0,0.15); border-radius: 3px; color: #ff8800;">
          ⚠️ 入力漏れ検出<br/>
          <span style="font-size: 10px; color: var(--text-muted);">${missingItems.join(", ")}</span>
        </div>
      `;
    } else {
      container.querySelector("#missing-result").innerHTML = `
        <div style="padding: 6px; background: rgba(68,170,68,0.15); border-radius: 3px; color: #44aa44;">
          ✓ 入力漏れなし
        </div>
      `;
    }

    // エラー一覧
    const errors = [];
    if (hasDuplicate) errors.push({ code: "DUP001", msg: "重複受注の可能性" });
    if (hasContradiction) errors.push({ code: "CON001", msg: "チャネル間で金額が相違" });
    if (missingItems.length > 0) errors.push({ code: "MIS001", msg: `必須項目が未入力: ${missingItems.join(", ")}` });

    if (errors.length > 0) {
      container.querySelector("#error-list").innerHTML = errors.map(e => `
        <div style="padding: 6px; margin-bottom: 4px; background: rgba(255,68,68,0.1); border-left: 2px solid #ff4444; border-radius: 2px;">
          <strong style="color: #ff6b6b;">${e.code}</strong><br/>
          <span style="color: var(--text-muted);">${e.msg}</span>
        </div>
      `).join("");
    } else {
      container.querySelector("#error-list").innerHTML = '<span style="color: var(--text-muted);">（エラーなし）</span>';
    }

    // 優先度リストを更新
    const priorityItems = errors.map((e, i) => ({
      優先度リストID: `priority-${i}`,
      優先度レベル: i + 1,
      エラー分類: e.code,
      修正ステータス: "未対応",
      信頼度スコア: 85 - i * 5
    }));
    renderPriorityList(priorityItems);
  }

  // ===== 5. 正規化ボタン =====
  container.querySelector("#btn-normalize").addEventListener("click", () => {
    if (!currentExtractedData) {
      alert("先にAI_OCR読み込みを実行してください");
      return;
    }
    alert("正規化ルールを適用しました");
    // 実際にはデータ正規化処理を実行
  });

  // ===== 6. 音声ガイダンス再生ボタン =====
  container.querySelector("#btn-voice-play").addEventListener("click", () => {
    alert("音声ガイダンス: 受注データを確認してください。問題がなければ確定ボタンを押してください。");
    // 実際にはAudio APIで音声再生
  });

  // ===== 7. 優先度リスト編集ボタン =====
  container.addEventListener("click", async e => {
    const editBtn = e.target.closest(".edit-priority-btn");
    if (editBtn) {
      const id = editBtn.dataset.id;
      window.showScreen("scr-1781413354977"); // 修正対象優先度リスト画面へ遷移
    }
  });
}

function(container, apiUrl, tables) {
  // テーブルインデックス
  const scoreTableIdx = 0;
  const correctionTableIdx = 1;

  let allScores = [];
  let selectedScoreId = null;
  let selectedFieldName = null;

  // ============ 1. 再描画関数 ============
  function renderScoreList(scores) {
    const tbody = container.querySelector("#score-tbody");
    if (!scores || scores.length === 0) {
      tbody.innerHTML = '<tr><td colspan="3" style="padding: 16px; text-align: center; color: var(--text-muted);">データがありません</td></tr>';
      return;
    }

    tbody.innerHTML = scores.map(score => {
      const scoreNum = score.総合スコア || 0;
      const warningLevel = score.警告レベル || "低";
      const warningColor = warningLevel === "高" ? "#ff5252" : warningLevel === "中" ? "#ff9800" : "#4caf50";

      return `
        <tr data-id="${score.信頼度スコアID}" style="cursor: pointer; border-bottom: 1px solid rgba(255,255,255,0.08); transition: background 0.2s;" onmouseover="this.style.background='rgba(255,255,255,0.05)'" onmouseout="this.style.background=''">
          <td style="padding: 8px; color: var(--text);">${score.受注データID ? score.受注データID.substring(0, 8) : "-"}</td>
          <td style="padding: 8px; text-align: center; color: var(--primary); font-weight: 600;">${scoreNum}</td>
          <td style="padding: 8px; text-align: center;"><span style="display: inline-block; width: 20px; height: 20px; border-radius: 50%; background: ${warningColor}; font-size: 10px; color: #fff; line-height: 20px; text-align: center;">${warningLevel.charAt(0)}</span></td>
        </tr>
      `;
    }).join("");
  }

  // ============ 2. 初期データ読み込み ============
  async function loadScores() {
    const rows = await window.aivicApi.list(scoreTableIdx);
    if (rows) {
      allScores = rows;
      renderScoreList(allScores);
    }
  }

  loadScores();

  // ============ 3. 検索・フィルタ ============
  container.querySelector("#btn-search").addEventListener("click", () => {
    const orderId = container.querySelector("#search-order-id").value.toLowerCase();
    const scoreRange = container.querySelector("#filter-score-range").value;
    const warningLevel = container.querySelector("#filter-warning-level").value;
    const sortBy = container.querySelector("#sort-by").value;

    let filtered = allScores.filter(s => {
      if (orderId && !s.受注データID?.toLowerCase().includes(orderId)) return false;
      if (scoreRange) {
        const score = s.総合スコア || 0;
        if (scoreRange === "0-50" && score > 50) return false;
        if (scoreRange === "51-75" && (score <= 50 || score > 75)) return false;
        if (scoreRange === "76-100" && score <= 75) return false;
      }
      if (warningLevel && s.警告レベル !== warningLevel) return false;
      return true;
    });

    // ソート
    if (sortBy === "score-asc") filtered.sort((a, b) => (a.総合スコア || 0) - (b.総合スコア || 0));
    else if (sortBy === "score-desc") filtered.sort((a, b) => (b.総合スコア || 0) - (a.総合スコア || 0));
    else if (sortBy === "priority-asc") filtered.sort((a, b) => (b.警告レベル === "高" ? 1 : -1));
    else if (sortBy === "date-desc") filtered.sort((a, b) => new Date(b.更新日時) - new Date(a.更新日時));

    renderScoreList(filtered);
  });

  container.querySelector("#btn-reset").addEventListener("click", () => {
    container.querySelector("#search-order-id").value = "";
    container.querySelector("#filter-score-range").value = "";
    container.querySelector("#filter-warning-level").value = "";
    container.querySelector("#sort-by").value = "score-asc";
    renderScoreList(allScores);
  });

  // ============ 4. 行クリックで詳細表示 ============
  container.addEventListener("click", async (e) => {
    const row = e.target.closest("tr[data-id]");
    if (!row) return;

    selectedScoreId = row.dataset.id;
    const score = allScores.find(s => s.信頼度スコアID === selectedScoreId);
    if (!score) return;

    // OCR結果表示
    container.querySelector("#ocr-preview").style.display = "block";
    container.querySelector("#ocr-empty").style.display = "none";
    container.querySelector("#score-overall").textContent = score.総合スコア || "-";
    container.querySelector("#warning-level-display").textContent = score.警告レベル || "-";
    container.querySelector("#score-completeness").textContent = score.完全性スコア || "-";
    container.querySelector("#score-accuracy").textContent = score.正確性スコア || "-";
    container.querySelector("#score-consistency").textContent = score.一貫性スコア || "-";

    // 抽出フィールド表示（サンプル）
    const fieldsHtml = `
      <div style="margin-bottom: 4px;"><strong>受注ID:</strong> ${score.受注データID || "-"}</div>
      <div style="margin-bottom: 4px;"><strong>検証ステータス:</strong> ${score.検証ステータス || "-"}</div>
      <div style="margin-bottom: 4px;"><strong>スコア計算日時:</strong> ${score.スコア計算日時? new Date(score.スコア計算日時).toLocaleString('ja-JP') : "-"}</div>
      <div><strong>備考:</strong> ${score.備考 || "-"}</div>
    `;
    container.querySelector("#extracted-fields").innerHTML = fieldsHtml;

    // 修正フォーム表示
    container.querySelector("#edit-form").style.display = "flex";
    container.querySelector("#edit-empty").style.display = "none";
    container.querySelector("#corrected-value").value = "";
    container.querySelector("#correction-reason").value = "";
    container.querySelector("#correction-comment").value = "";

    // 修正前後比較表示
    container.querySelector("#comparison-panel").style.display = "block";
    container.querySelector("#comparison-empty").style.display = "none";
    container.querySelector("#before-value").textContent = score.総合スコア || "-";
    container.querySelector("#after-value").textContent = "-";
  });

  // ============ 5. 修正を保存 ============
  container.querySelector("#btn-save-correction").addEventListener("click", async () => {
    const correctedValue = container.querySelector("#corrected-value").value.trim();
    const reason = container.querySelector("#correction-reason").value;
    const comment = container.querySelector("#correction-comment").value.trim();

    if (!correctedValue || !reason) {
      alert("修正値と修正理由を入力してください");
      return;
    }

    if (!selectedScoreId) {
      alert("修正対象が選択されていません");
      return;
    }

    const score = allScores.find(s => s.信頼度スコアID === selectedScoreId);
    if (!score) return;

    // 修正履歴を保存
    const correctionRecord = {
      受注データID: score.受注データID,
      修正項目名: "総合スコア",
      修正前値: String(score.総合スコア || ""),
      修正後値: correctedValue,
      修正理由: reason,
      修正備考: comment,
      修正ユーザーID: "current-user",
      修正日時: new Date().toISOString(),
      検証結果ID: score.検証結果ID || null
    };

    const saved = await window.aivicApi.save(correctionTableIdx, correctionRecord);
    if (saved) {
      alert("修正を保存しました");
      container.querySelector("#after-value").textContent = correctedValue;
      container.querySelector("#corrected-value").value = "";
      container.querySelector("#correction-reason").value = "";
      container.querySelector("#correction-comment").value = "";
    }
  });

  container.querySelector("#btn-cancel-correction").addEventListener("click", () => {
    container.querySelector("#corrected-value").value = "";
    container.querySelector("#correction-reason").value = "";
    container.querySelector("#correction-comment").value = "";
    container.querySelector("#after-value").textContent = "-";
  });
}

function(container, apiUrl, tables) {
  // テーブルインデックス（データ構造から推測）
  const validationResultsIdx = 0;  // 受注データ検証結果
  const trustScoreIdx = 1;         // 信頼度スコア
  const duplicateDetectionIdx = 2; // 重複受注検出結果
  const channelConflictIdx = 3;    // チャネル間矛盾検出結果
  const missingInputIdx = 4;       // 入力漏れ検出結果
  const ocrResultIdx = 5;          // AI_OCR読み込み結果

  let allRows = [];
  let selectedRows = new Set();
  let processLog = [];

  // ===== ログ追加関数 =====
  function addLog(message, level = 'info') {
    const timestamp = new Date().toLocaleTimeString('ja-JP');
    const prefix = level === 'error' ? '[エラー]' : level === 'success' ? '[成功]' : '[情報]';
    const logEntry = `${timestamp} ${prefix} ${message}`;
    processLog.push(logEntry);

    const logEl = container.querySelector('#process-log');
    logEl.textContent = processLog.slice(-50).join('\n');
    logEl.scrollTop = logEl.scrollHeight;
  }

  // ===== テーブル再描画関数 =====
  function renderRows(rows) {
    const tbody = container.querySelector('#revalidation-tbody');
    if (!rows || rows.length === 0) {
      tbody.innerHTML = '<tr style="background: var(--bg-main); border-bottom: 1px solid var(--border);"><td colspan="7" style="padding: 24px; text-align: center; color: var(--text-muted);">検証対象受注がありません</td></tr>';
      return;
    }

    tbody.innerHTML = rows.map(r => `
      <tr style="background: var(--bg-main); border-bottom: 1px solid var(--border);" data-id="${r.id || ''}">
        <td style="padding: 8px 12px; border-right: 1px solid var(--border); text-align: center;">
          <input type="checkbox" class="row-select" data-id="${r.id || ''}" style="accent-color: var(--primary);" />
        </td>
        <td style="padding: 8px 12px; border-right: 1px solid var(--border); color: var(--text);">${r.受注データID || r.order_id || '-'}</td>
        <td style="padding: 8px 12px; border-right: 1px solid var(--border); color: var(--text);">${r.チャネルコード || r.channel_code || '-'}</td>
        <td style="padding: 8px 12px; border-right: 1px solid var(--border);">
          <span style="display: inline-block; padding: 2px 6px; border-radius: 3px; font-size: 11px; font-weight: 500; ${
            r.検証ステータス === '合格' ? 'background: rgba(76,175,80,0.2); color: #4caf50;' :
            r.検証ステータス === '不合格' ? 'background: rgba(244,67,54,0.2); color: #f44336;' :
            r.検証ステータス === '警告' ? 'background: rgba(255,193,7,0.2); color: #ffc107;' :
            'background: rgba(158,158,158,0.2); color: #9e9e9e;'
          }">
            ${r.検証ステータス || r.validation_status || '未検証'}
          </span>
        </td>
        <td style="padding: 8px 12px; border-right: 1px solid var(--border); text-align: center; color: var(--text);">${r.総合スコア || r.overall_score || '-'}</td>
        <td style="padding: 8px 12px; border-right: 1px solid var(--border); text-align: center; color: var(--text);">${r.優先度レベル || r.priority_level || '-'}</td>
        <td style="padding: 8px 12px; color: var(--text-muted); font-size: 11px;">${r.検証実行日時 ? new Date(r.検証実行日時).toLocaleString('ja-JP') : '-'}</td>
      </tr>
    `).join('');

    // チェックボックスイベント
    container.querySelectorAll('.row-select').forEach(cb => {
      cb.addEventListener('change', e => {
        if (e.target.checked) {
          selectedRows.add(e.target.dataset.id);
        } else {
          selectedRows.delete(e.target.dataset.id);
        }
        updateSelectAllCheckbox();
      });
    });
  }

  // ===== 全選択チェックボックス更新 =====
  function updateSelectAllCheckbox() {
    const selectAll = container.querySelector('#select-all');
    const checkboxes = container.querySelectorAll('.row-select');
    selectAll.checked = checkboxes.length > 0 && Array.from(checkboxes).every(cb => cb.checked);
  }

  // ===== 初期データ読み込み =====
  async function loadInitialData() {
    try {
      const rows = await window.aivicApi.list(validationResultsIdx);
      allRows = rows || tables[validationResultsIdx]?.records || [];
      renderRows(allRows);
      addLog(`初期データ読み込み完了: ${allRows.length}件`);
    } catch (e) {
      addLog(`初期データ読み込みエラー: ${e.message}`, 'error');
      renderRows(tables[validationResultsIdx]?.records || []);
    }
  }

  // ===== フィルタ適用 =====
  container.querySelector('#btn-filter').addEventListener('click', async () => {
    const orderId = container.querySelector('#filter-order-id').value.trim();
    const channel = container.querySelector('#filter-channel').value;
    const status = container.querySelector('#filter-status').value;

    let filtered = allRows;
    if (orderId) {
      filtered = filtered.filter(r => (r.受注データID || r.order_id || '').includes(orderId));
    }
    if (channel) {
      filtered = filtered.filter(r => (r.チャネルコード || r.channel_code) === channel);
    }
    if (status) {
      filtered = filtered.filter(r => (r.検証ステータス || r.validation_status) === status);
    }

    renderRows(filtered);
    addLog(`フィルタ適用: ${filtered.length}件`);
  });

  // ===== フィルタリセット =====
  container.querySelector('#btn-reset-filter').addEventListener('click', () => {
    container.querySelector('#filter-order-id').value = '';
    container.querySelector('#filter-channel').value = '';
    container.querySelector('#filter-status').value = '';
    renderRows(allRows);
    addLog('フィルタリセット');
  });

  // ===== 全選択チェックボックス =====
  container.querySelector('#select-all').addEventListener('change', e => {
    container.querySelectorAll('.row-select').forEach(cb => {
      cb.checked = e.target.checked;
      if (e.target.checked) {
        selectedRows.add(cb.dataset.id);
      } else {
        selectedRows.delete(cb.dataset.id);
      }
    });
  });

  // ===== 一括再検証実行 =====
  container.querySelector('#btn-batch-revalidate').addEventListener('click', async () => {
    if (selectedRows.size === 0) {
      addLog('再検証対象が選択されていません', 'error');
      return;
    }

    const rules = [];
    if (container.querySelector('#rule-duplicate').checked) rules.push('重複検出');
    if (container.querySelector('#rule-channel-conflict').checked) rules.push('チャネル矛盾検出');
    if (container.querySelector('#rule-missing-input').checked) rules.push('入力漏れ検出');
    if (container.querySelector('#rule-ocr-confidence').checked) rules.push('OCR信頼度確認');
    if (container.querySelector('#rule-data-format').checked) rules.push('データ形式検証');
    if (container.querySelector('#rule-completeness').checked) rules.push('完全性スコア算出');

    if (rules.length === 0) {
      addLog('検証ルールが選択されていません', 'error');
      return;
    }

    addLog(`一括再検証開始: ${selectedRows.size}件, ルール: ${rules.join(', ')}`);

    try {
      let successCount = 0;
      for (const orderId of selectedRows) {
        // シミュレーション: 実際のAPI呼び出しに置き換え
        await new Promise(resolve => setTimeout(resolve, 100));
        successCount++;
      }
      addLog(`一括再検証完了: ${successCount}件成功`, 'success');
      await loadInitialData();
    } catch (e) {
      addLog(`一括再検証エラー: ${e.message}`, 'error');
    }
  });

  // ===== 個別再検証実行 =====
  container.querySelector('#btn-individual-revalidate').addEventListener('click', () => {
    if (selectedRows.size === 0) {
      addLog('再検証対象が選択されていません', 'error');
      return;
    }
    if (selectedRows.size > 1) {
      addLog('1件のみ選択してください', 'error');
      return;
    }

    const orderId = Array.from(selectedRows)[0];
    addLog(`個別再検証実行: ${orderId}`);

    // 詳細画面へ遷移
    window.showScreen('scr-1781413282852');
  });

  // ===== スコア算出・更新 =====
  container.querySelector('#btn-score-calculate').addEventListener('click', async () => {
    if (selectedRows.size === 0) {
      addLog('スコア算出対象が選択されていません', 'error');
      return;
    }

    addLog(`スコア算出・更新開始: ${selectedRows.size}件`);

    try {
      let successCount = 0;
      for (const orderId of selectedRows) {
        // シミュレーション
        await new Promise(resolve => setTimeout(resolve, 150));
        successCount++;
      }
      addLog(`スコア算出・更新完了: ${successCount}件成功`, 'success');
      await loadInitialData();
    } catch (e) {
      addLog(`スコア算出エラー: ${e.message}`, 'error');
    }
  });

  // ===== ログクリア =====
  container.querySelector('#btn-clear-log').addEventListener('click', () => {
    processLog = [];
    container.querySelector('#process-log').textContent = '(ログクリア)';
    addLog('ログクリア実行');
  });

  // ===== 初期化 =====
  loadInitialData();
}
